"""Original synthetic graduate regression/prediction lessons. No external data inputs.
Run: python scripts/build_lessons_4_6.py. All case numbers come from executed labs.
"""
import json
from course_common import render_lesson, table, bars, line_chart, write_lab, esc, ROOT


def p(text): return '<p>'+text+'</p>'
def eq(text): return '<div class="formula" role="note">'+text+'</div>'
def ul(*items): return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def f(x,d=3): return f'{x:,.{d}f}'
def section(id,title,body,check=None,answer=None):
    return dict(id=id,title=title,body=body,check=check,answer=answer)
def scatter(points,title,xlabel,ylabel,reference=False):
    xs=[a[0] for a in points];ys=[a[1] for a in points]
    xmin,xmax=min(xs),max(xs);ymin,ymax=min(ys),max(ys)
    if reference: xmin=ymin=min(xmin,ymin);xmax=ymax=max(xmax,ymax)
    dx=xmax-xmin or 1;dy=ymax-ymin or 1
    px=lambda a:70+600*(a-xmin)/dx;py=lambda b:270-230*(b-ymin)/dy
    marks=''.join(f'<circle cx="{px(x):.2f}" cy="{py(y):.2f}" r="4" fill="#276451" opacity=".7"/>' for x,y in points)
    if reference: marks+=f'<line x1="{px(xmin)}" y1="{py(xmin)}" x2="{px(xmax)}" y2="{py(xmax)}" stroke="#ab4e24" stroke-dasharray="6 4"/>'
    axis=''.join(f'<text x="{70+i*150}" y="293" text-anchor="middle" font-size="13">{xmin+i*dx/4:.3g}</text><text x="62" y="{275-i*57.5}" text-anchor="end" font-size="13">{ymin+i*dy/4:.3g}</text>' for i in range(5))
    return '<figure><svg viewBox="0 0 720 340" role="img" aria-label="'+esc(title)+'"><title>'+esc(title)+'</title><desc>'+esc(xlabel+' versus '+ylabel)+'. All plotted values are in the following accessible table.</desc><path d="M70 35 V270 H680" fill="none" stroke="#44564a"/>'+axis+marks+'<text x="370" y="325" text-anchor="middle">'+esc(xlabel)+'</text></svg><figcaption>'+esc(title)+'. Vertical axis: '+esc(ylabel)+'. Synthetic observations only.</figcaption></figure>'+table([xlabel,ylabel],[[f(x),f(y)] for x,y in points],title+' — plotted values')

LAB4=r'''"""Lesson 4: original fictional Juniper workshop, seed 440731.
DGP: independent X~Uniform(1,16), Z~N(0,1),
Y=20+5X+0.18X^2+5sin(X/3)+(3+0.35X)Z, n=180.
Y is completion minutes, X is batch size in standardized crate units.
Other examples use independent random draws from the same seeded stream.
No downloads, source records, historical outputs or external files are used.
"""
import json
import numpy as np
from sklearn.model_selection import KFold, train_test_split
rng=np.random.default_rng(440731)
def ols(X,y):
    b=np.linalg.lstsq(X,y,rcond=None)[0];e=y-X@b
    return b,e,float(e@e)
def design(x,kind):
    if kind=='hinge': return np.column_stack([np.ones(len(x)),x,np.maximum(x-8,0)])
    degree={'line':1,'quadratic':2,'cubic':3}[kind]
    return np.vander(x,degree+1,increasing=True)
def lowess(x,y,grid,frac=.35):
    out=[];k=int(np.ceil(len(x)*frac))
    for a in grid:
        d=np.abs(x-a);h=np.sort(d)[k-1];w=np.maximum(1-(d/h)**3,0)**3
        X=np.column_stack([np.ones(len(x)),x-a]);b=np.linalg.lstsq(X*np.sqrt(w[:,None]),y*np.sqrt(w),rcond=None)[0];out.append(float(b[0]))
    return out
n=180;x=rng.uniform(1,16,n);mu=20+5*x+.18*x*x+5*np.sin(x/3);y=mu+(3+.35*x)*rng.normal(size=n)
X=design(x,'line');b,e,sse=ols(X,y);tss=float(((y-y.mean())**2).sum());ess=float(((X@b-y.mean())**2).sum());grid=np.linspace(1,16,13)
bins=[]
for a,z in zip(np.linspace(1,16,7)[:-1],np.linspace(1,16,7)[1:]):
    m=(x>=a)&(x<z);bins.append([float(a),float(z),int(m.sum()),float(x[m].mean()),float(y[m].mean()),float(e[m].mean())])
# Five new simulated rows for a hand-verifiable calculation.
tx=np.arange(1.,6.);ty=7+2.5*tx+rng.integers(-3,4,5);tb,te,tsse=ols(design(tx,'line'),ty)
hand=dict(x=tx.tolist(),y=ty.tolist(),xbar=float(tx.mean()),ybar=float(ty.mean()),sxx=float(((tx-tx.mean())**2).sum()),sxy=float(((tx-tx.mean())*(ty-ty.mean())).sum()),b=tb.tolist(),fitted=(design(tx,'line')@tb).tolist(),resid=te.tolist(),sse=tsse)
# Independent transformed-outcome examples, not transformations of the first outcome.
u=rng.uniform(1,12,200)
y_ll=np.exp(2.8+.11*u+rng.normal(0,.2,len(u)))
y_lg=40+15*np.log(u)+rng.normal(0,4,len(u))
y_gg=np.exp(2+.7*np.log(u)+rng.normal(0,.18,len(u)))
bll,ell,_=ols(design(u,'line'),np.log(y_ll));blg,_,_=ols(design(np.log(u),'line'),y_lg);bgg,egg,_=ols(design(np.log(u),'line'),np.log(y_gg))
ug=np.linspace(1,12,12);smear=float(np.exp(ell).mean())
trans=dict(log_level=bll.tolist(),level_log=blg.tolist(),log_log=bgg.tolist(),pct_one=float(100*np.expm1(bll[1])),level_ten=float(blg[1]*np.log(1.1)),pct_ten=float(100*np.expm1(bgg[1]*np.log(1.1))),smear=smear,grid=ug.tolist(),log_level_median=np.exp(bll[0]+bll[1]*ug).tolist(),log_level_mean=(smear*np.exp(bll[0]+bll[1]*ug)).tolist(),level_log_fit=(blg[0]+blg[1]*np.log(ug)).tolist(),log_log_fit=np.exp(bgg[0]+bgg[1]*np.log(ug)).tolist())
# A deliberately constructed sensitivity row is marked, never disguised as observed data.
xa=np.r_[x,35.];ya=np.r_[y,280.];Xa=design(xa,'line');ba,ea,ssa=ols(Xa,ya);hat=np.sum((Xa@np.linalg.inv(Xa.T@Xa))*Xa,axis=1);s2=ssa/(len(xa)-2);cook=ea**2/(2*s2)*hat/(1-hat)**2
j=int(np.argmax(cook));influence=dict(index=j,point=[float(xa[j]),float(ya[j])],h=float(hat[j]),resid=float(ea[j]),cook=float(cook[j]),slope_original=float(b[1]),slope_augmented=float(ba[1]),mean_h=float(hat.mean()),threshold=float(4/len(xa)))
# Measurement/selection are descriptive sensitivity examples, not causal estimators.
measured=x+rng.normal(0,3,n);bnoise,_,_=ols(design(measured,'line'),y)
keep=y>np.median(y);bsel,_,_=ols(design(x[keep],'line'),y[keep])
# Predeclared validation: hold out 25%, use 5-fold CV only in development.
dev,test=train_test_split(np.arange(n),test_size=.25,random_state=440732)
folds=list(KFold(5,shuffle=True,random_state=440733).split(dev));rows=[];cv={}
for kind in ['line','quadratic','cubic','hinge']:
    D=design(x,kind);bb,ee,ss=ols(D[dev],y[dev]);oof=np.empty(len(dev))
    for tr,va in folds:
        bf,_,_=ols(D[dev[tr]],y[dev[tr]]);oof[va]=D[dev[va]]@bf
    mse=float(np.mean((y[dev]-oof)**2));cv[kind]=mse
    rows.append(dict(model=kind,p=D.shape[1],train_rmse=float(np.sqrt(ss/len(dev))),cv_rmse=float(np.sqrt(mse))))
chosen=min(cv,key=cv.get);bc,_,_=ols(design(x[dev],chosen),y[dev]);testpred=design(x[test],chosen)@bc;test_rmse=float(np.sqrt(np.mean((y[test]-testpred)**2)))
quad,_,_=ols(design(x,'quadratic'),y);hinge,_,_=ols(design(x,'hinge'),y)
curve={kind:(design(grid,kind)@ols(design(x,kind),y)[0]).tolist() for kind in ['line','quadratic','cubic','hinge']}
# Exact OLS geometry is tested computationally.
assert np.isclose(tss,ess+sse)
assert abs(e.sum())<1e-8 and abs(x@e)<1e-7
assert len(set(dev)&set(test))==0
print(json.dumps(dict(seed=440731,n=n,x_min=float(x.min()),x_max=float(x.max()),mean_y=float(y.mean()),b=b.tolist(),sse=sse,tss=tss,ess=ess,r2=1-sse/tss,rmse=float(np.sqrt(sse/n)),residual_sd=float(np.sqrt(sse/(n-2))),variance=float(tss/(n-1)),resid_sum=float(e.sum()),x_resid=float(x@e),grid=grid.tolist(),truth=(20+5*grid+.18*grid*grid+5*np.sin(grid/3)).tolist(),ols_curve=(design(grid,'line')@b).tolist(),lowess=lowess(x,y,grid),bins=bins,scatter=np.column_stack([x[:36],y[:36]]).tolist(),residual_scatter=np.column_stack([x[:36],e[:36]]).tolist(),hand=hand,trans=trans,influence=influence,sensitivity=dict(clean=float(b[1]),noisy=float(bnoise[1]),selected=float(bsel[1]),selected_n=int(keep.sum())),validation=rows,selected=chosen,development_n=len(dev),test_n=len(test),test_rmse=test_rmse,quadratic=quad.tolist(),quadratic_slopes=[float(quad[1]+2*quad[2]*v) for v in [4,8,12]],hinge=hinge.tolist(),hinge_slopes=[float(hinge[1]),float(hinge[1]+hinge[2])],curves=curve)))
'''

LAB5=r'''"""Lesson 5: original fictional Cedar calibration rigs, seed 550829.
E~Uniform(0,12); D~Bernoulli(logit^-1(-1+.2E)); A~Uniform(0,1).
Bench C has probabilities (.4,.35,.25); Ec=E-6.
Y=70+2Ec-.08Ec^2+5D+1.1D*Ec+4A+.7Ec*A+offset(C)+(3+.4E)Z.
offset(amber,blue,copper)=(0,4,-3), independent Z~N(0,1); n=260.
Y: calibration units/hour; E: service years; D: powered fixture; A: tool setting.
The separate Gaussian interval experiment has Y=12+2X+4Z, X~Uniform(0,10).
No external inputs. The fixture assignment is associated with service age.
"""
import json
import numpy as np
from scipy.stats import t, f, chi2
from sklearn.model_selection import KFold
rng=np.random.default_rng(550829)
def fit(X,y):
    b=np.linalg.lstsq(X,y,rcond=None)[0];e=y-X@b;n,p=X.shape;inv=np.linalg.inv(X.T@X);sse=float(e@e);s2=sse/(n-p);h=np.sum((X@inv)*X,axis=1)
    hc3=inv@((X.T*(e/(1-h))**2)@X)@inv
    return dict(b=b,e=e,sse=sse,s2=s2,cov=s2*inv,hc3=hc3,h=h,n=n,p=p)
# Exact-normal finite-sample interval illustration, explicitly separate from heteroskedastic case.
x=rng.uniform(0,10,80);y=12+2*x+4*rng.normal(size=80);X=np.column_stack([np.ones(80),x]);a=fit(X,y);q=t.ppf(.975,78)
intervals=[]
for x0 in [0,5,10,12]:
    v=np.array([1.,x0]);pred=float(v@a['b']);se=float(np.sqrt(v@a['cov']@v));spe=float(np.sqrt(se*se+a['s2']))
    intervals.append(dict(x=x0,pred=pred,mean_lo=pred-q*se,mean_hi=pred+q*se,pred_lo=pred-q*spe,pred_hi=pred+q*spe,se_mean=se,se_pred=spe))
levels=[]
for level in [.9,.95,.99]:
    crit=t.ppf((1+level)/2,78);se=np.sqrt(a['cov'][1,1]);levels.append([level,float(a['b'][1]-crit*se),float(a['b'][1]+crit*se)])
coverage=[]
for repeat in range(400):
    yy=12+2*x+4*rng.normal(size=80);af=fit(X,yy);se=np.sqrt(af['cov'][1,1]);coverage.append([float(af['b'][1]),float(af['b'][1]-q*se),float(af['b'][1]+q*se)])
cover=float(np.mean([lo<=2<=hi for est,lo,hi in coverage]))
# Main case: all compared fits use the exact same 260 rows.
n=260;E=rng.uniform(0,12,n);Ec=E-6;D=rng.binomial(1,1/(1+np.exp(-(-1+.2*E))));A=rng.uniform(0,1,n);C=rng.choice(3,n,p=[.4,.35,.25]);Z=rng.normal(size=n)
mu=70+2*Ec-.08*Ec**2+5*D+1.1*D*Ec+4*A+.7*Ec*A+np.choose(C,[0,4,-3]);Y=mu+(3+.4*E)*Z
short=fit(np.column_stack([np.ones(n),D]),Y);add=fit(np.column_stack([np.ones(n),D,Ec]),Y);aux=fit(np.column_stack([np.ones(n),D]),Ec)
controls=np.column_stack([np.ones(n),Ec]);rD=D-controls@np.linalg.lstsq(controls,D,rcond=None)[0];rY=Y-controls@np.linalg.lstsq(controls,Y,rcond=None)[0];fwl=float(rD@rY/(rD@rD));ovb=float(add['b'][1]+add['b'][2]*aux['b'][1])
M=np.column_stack([np.ones(n),D,Ec,Ec**2,D*Ec,A,Ec*A,C==1,C==2]);names=['Intercept at E=6, A=0, amber','Powered fixture','Service years centered','Service years squared','Fixture × service years','Tool setting','Service years × tool setting','Blue bench','Copper bench'];full=fit(M,Y)
# Robust contrasts: asymptotic normal critical value; no claim of exact finite-sample coverage.
from scipy.stats import norm
contrasts=[]
for val in [3,6,9]:
    v=np.zeros(M.shape[1]);v[1]=1;v[4]=val-6;est=float(v@full['b']);se=float(np.sqrt(v@full['hc3']@v));contrasts.append([val,est,est-norm.ppf(.975)*se,est+norm.ppf(.975)*se])
# Drop curvature and fixture interaction together (2 restrictions).
restricted=np.delete(M,[3,4],axis=1);red=fit(restricted,Y);F=((red['sse']-full['sse'])/2)/(full['sse']/(n-M.shape[1]));Fp=float(f.sf(F,2,n-M.shape[1]));R=np.eye(M.shape[1])[[3,4]];W=float((R@full['b'])@np.linalg.solve(R@full['hc3']@R.T,R@full['b']));Wp=float(chi2.sf(W,2))
# Reference change: copper becomes baseline; fitted values are unchanged.
Mc=M.copy();Mc[:,7]=C==0;Mc[:,8]=C==1;fc=fit(Mc,Y);reference_error=float(np.max(np.abs(M@full['b']-Mc@fc['b'])))
# Residual audit uses predictions from models that did not see the held-out row.
oof=np.empty(n)
for tr,va in KFold(5,shuffle=True,random_state=550830).split(M):
    oof[va]=M[va]@np.linalg.lstsq(M[tr],Y[tr],rcond=None)[0]
er=Y-oof;largest=np.argsort(np.abs(er))[-5:][::-1]
residual_rows=[[int(i),float(Y[i]),float(oof[i]),float(er[i]),float(E[i])] for i in largest]
# Finite-sample identity must hold even though the additive model omits real terms.
assert np.isclose(short['b'][1],ovb,rtol=1e-10)
assert np.isclose(fwl,add['b'][1],rtol=1e-10)
assert reference_error<1e-8
counts=[[label,int((C==k).sum()),float(Y[C==k].mean())] for k,label in enumerate(['Amber','Blue','Copper'])]
fullcoef=[[names[i],float(full['b'][i]),float(np.sqrt(full['cov'][i,i])),float(np.sqrt(full['hc3'][i,i]))] for i in range(M.shape[1])]
print(json.dumps(dict(seed=550829,n=n,interval_b=a['b'].tolist(),interval_s=float(np.sqrt(a['s2'])),intervals=intervals,levels=levels,coverage=cover,repetitions=len(coverage),coverage_first=coverage[:16],short=short['b'].tolist(),add=add['b'].tolist(),aux=aux['b'].tolist(),fwl=fwl,ovb_reconstructed=ovb,shift=float(short['b'][1]-add['b'][1]),product=float(add['b'][2]*aux['b'][1]),rD2=float(rD@rD),D2=float(((D-D.mean())**2).sum()),fixture_prevalence=float(D.mean()),fullcoef=fullcoef,full_b=full['b'].tolist(),contrasts=contrasts,F=float(F),F_p=Fp,W=W,W_p=Wp,q=2,df=n-M.shape[1],restricted_sse=red['sse'],full_sse=full['sse'],counts=counts,reference_error=reference_error,copper_intercept=float(fc['b'][0]),amber_intercept=float(full['b'][0]),oof_rmse=float(np.sqrt(np.mean(er**2))),training_rmse=float(np.sqrt(np.mean(full['e']**2))),residual_rows=residual_rows,scatter=np.column_stack([Y[:36],oof[:36]]).tolist(),resid_plot=np.column_stack([oof[:36],er[:36]]).tolist(),continuous_slopes=[float(full['b'][5]+full['b'][6]*(v-6)) for v in [3,6,9]],quadratic_slopes=[float(full['b'][2]+2*full['b'][3]*(v-6)+full['b'][4]+full['b'][6]*.5) for v in [3,6,9]],group_means=[float(Y[D==v].mean()) for v in [0,1]],experience_means=[float(E[D==v].mean()) for v in [0,1]],residual_mean=float(er.mean()))))
'''

LAB6=r'''"""Lesson 6: original fictional Mica dispatch costs, seed 660913.
DGP n=604: distance U(1,25), size U(1,12), priority Bernoulli(.25), weather N(0,1),
hub categorical probabilities (.4,.35,.25), 20 independent normal distractors.
log(cost)=3.2+.035*distance+.055*size+.12*priority+.15*weather
          +.012*distance*priority+hub_offset+.08*sin(distance/3)+.28Z.
hub_offset=(0,.12,-.08); Z independent N(0,1). Cost is fictional credits.
Size/weather missing completely at random with probability .08; distractors .05.
Predeclare 75% development, 25% final evaluation; five shuffled development folds.
All imputation, scaling, coefficient fitting and smearing are fitted within each fold.
Separate original simulations demonstrate loss, optimism and information criteria.
No external inputs, inherited fitted outputs or historical source records.
"""
import json
import numpy as np
from scipy.stats import t
from sklearn.model_selection import train_test_split,KFold
from sklearn.pipeline import make_pipeline
from sklearn.impute import SimpleImputer
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import Lasso,LinearRegression
rng=np.random.default_rng(660913)
# Loss changes the population functional being estimated.
outcomes=rng.lognormal(3,.65,3000);mean=float(outcomes.mean());median=float(np.median(outcomes));p80=float(np.quantile(outcomes,.8))
loss=[]
for label,v in [('Mean',mean),('Median',median),('80th percentile',p80)]:
    loss.append([label,v,float(np.mean((outcomes-v)**2)),float(np.mean(np.abs(outcomes-v))),float(np.mean(4*np.maximum(outcomes-v,0)+np.maximum(v-outcomes,0)))])
# Bias/variance demonstration, independent of main case. True curve: 8+3x+4x^2.
grid=np.linspace(-1,1,41);truth=8+3*grid+4*grid**2;sim=[]
for degree in [1,3,9]:
    preds=[];trainloss=[]
    for j in range(160):
        xx=rng.uniform(-1,1,45);yy=8+3*xx+4*xx**2+rng.normal(0,2,45);X=np.vander(xx,degree+1,increasing=True);b=np.linalg.lstsq(X,yy,rcond=None)[0];preds.append(np.vander(grid,degree+1,increasing=True)@b);trainloss.append(float(np.mean((yy-X@b)**2)))
    P=np.array(preds);bias2=float(np.mean((P.mean(axis=0)-truth)**2));variance=float(np.mean(P.var(axis=0,ddof=0)));sim.append([degree,float(np.mean(trainloss)),bias2,variance,4.,bias2+variance+4])
# Same-data Gaussian likelihood comparison, including unknown variance in k.
qx=rng.uniform(-1,1,140);qy=45+10*qx+12*qx**2+rng.normal(0,5,140);criteria=[]
for degree in [1,2,3,6]:
    Q=np.vander(qx,degree+1,increasing=True);b=np.linalg.lstsq(Q,qy,rcond=None)[0];e=qy-Q@b;sse=float(e@e);k=degree+2;n=len(qx);minus2=n*(np.log(2*np.pi)+1+np.log(sse/n));criteria.append([degree,k,sse,float(minus2+2*k),float(minus2+np.log(n)*k)])
Q=np.vander(qx,3,increasing=True);b=np.linalg.lstsq(Q,qy,rcond=None)[0];e=qy-Q@b;s2=float(e@e/(140-3));v=np.array([1,.5,.25]);pred=float(v@b);sem=float(np.sqrt(s2*v@np.linalg.inv(Q.T@Q)@v));sep=float(np.sqrt(sem**2+s2));crit=t.ppf(.975,137);example_interval=[pred,pred-crit*sem,pred+crit*sem,pred-crit*sep,pred+crit*sep]

def generate(n,shift=False):
    distance=rng.uniform(20,40,n) if shift else rng.uniform(1,25,n)
    size=rng.uniform(1,12,n);priority=rng.binomial(1,.25,n);weather=rng.normal(size=n);hub=rng.choice(3,n,p=[.4,.35,.25]);noise=rng.normal(size=(n,20))
    logmu=3.2+.035*distance+.055*size+.12*priority+.15*weather+.012*distance*priority+np.choose(hub,[0,.12,-.08])+.08*np.sin(distance/3)+(.12 if shift else 0)
    y=np.exp(logmu+.28*rng.normal(size=n))
    # Build interactions after recording raw missing values, so missingness propagates.
    size[rng.random(n)<.08]=np.nan;weather[rng.random(n)<.08]=np.nan;noise[rng.random((n,20))<.05]=np.nan
    X=np.column_stack([distance,size,priority,weather,hub==1,hub==2,distance**2,size**2,distance*size,distance*priority,noise])
    return X,y
scale_x=np.arange(2.,12.,2.);scale_mean=float(scale_x.mean());scale_sd=float(scale_x.std(ddof=0));scale_z=(scale_x-scale_mean)/scale_sd
scaling_example=dict(x=scale_x.tolist(),z=scale_z.tolist(),mean=scale_mean,sd=scale_sd,raw_slope=2.5,scaled_slope=float(2.5*scale_sd),soft_z=.8,alpha=.15,soft_solution=float(max(.8-.15,0)))
names=['Distance','Size','Priority','Weather','Hub blue','Hub copper','Distance squared','Size squared','Distance × size','Distance × priority']+[f'Noise {i+1}' for i in range(20)]
X,y=generate(604);dev,test=train_test_split(np.arange(len(y)),test_size=.25,random_state=660914);folds=list(KFold(5,shuffle=True,random_state=660915).split(dev));alphas=np.logspace(-3,0,9)
def pipeline(alpha):
    estimator=LinearRegression() if alpha is None else Lasso(alpha=float(alpha),max_iter=100000,tol=1e-9)
    return make_pipeline(SimpleImputer(strategy='median'),StandardScaler(),estimator)
def fit_predict(tr,va,alpha,cols=None):
    cols=np.arange(X.shape[1]) if cols is None else cols
    model=pipeline(alpha);model.fit(X[tr][:,cols],np.log(y[tr]));smear=float(np.exp(np.log(y[tr])-model.predict(X[tr][:,cols])).mean());pred=smear*np.exp(model.predict(X[va][:,cols]));return model,smear,pred
search=[];oofs={};fold_results={}
for alpha in alphas:
    oof=np.empty(len(dev));fr=[]
    for train,valid in folds:
        model,smear,pred=fit_predict(dev[train],dev[valid],alpha);oof[valid]=pred;se=(y[dev[valid]]-pred)**2;fr.append([len(valid),float(se.sum()),float(np.sqrt(se.mean()))])
    mse=float(np.mean((y[dev]-oof)**2));search.append([float(alpha),float(np.sqrt(mse))]);oofs[float(alpha)]=oof;fold_results[float(alpha)]=fr
best=min(search,key=lambda r:r[1])[0]
# Compare declared feature sets on same rows/folds; only alpha search selects final LASSO.
feature_comparisons=[]
for label,cols in [('Core: distance, size, priority',np.arange(3)),('Context: core + weather + hub',np.arange(6)),('Expanded: context + shapes + noise',np.arange(30))]:
    oof=np.empty(len(dev))
    for tr,va in folds:
        model,smear,pred=fit_predict(dev[tr],dev[va],None,cols);oof[va]=pred
    model,smear,training=fit_predict(dev,dev,None,cols)
    feature_comparisons.append([label,len(cols)+1,float(np.sqrt(np.mean((y[dev]-training)**2))),float(np.sqrt(np.mean((y[dev]-oof)**2)))])
# Final procedure frozen: minimum CV original-scale RMSE alpha; median imputation;
# standardized expanded design; log target; global training smearing; no post-test tuning.
final,smear,testpred=fit_predict(dev,test,best);trainpred=smear*np.exp(final.predict(X[dev]));base=float(y[dev].mean());res=y[test]-testpred
scores=[]
for label,prediction in [('Development mean baseline',np.full(len(test),base)),('Frozen LASSO + smearing',testpred)]:
    err=y[test]-prediction;scores.append([label,float(np.sqrt(np.mean(err**2))),float(np.mean(np.abs(err))),float(np.mean(err))])
medpred=np.exp(final.predict(X[test]));median_rmse=float(np.sqrt(np.mean((y[test]-medpred)**2)));log_rmse=float(np.sqrt(np.mean((np.log(y[test])-final.predict(X[test]))**2)))
# Coefficient path uses development data only. It is descriptive, not another selection rule.
path=[]
for alpha in alphas:
    model,sm,pr=fit_predict(dev,dev,float(alpha));est=model[-1];path.append([float(alpha)]+est.coef_[:10].tolist()+[int(np.count_nonzero(np.abs(est.coef_)>1e-10)),float(est.dual_gap_),int(est.n_iter_)])
est=final[-1];coef=[[name,float(v),float(final[1].scale_[i])] for i,(name,v) in enumerate(zip(names,est.coef_)) if abs(v)>1e-10]
# Explain a leakage boundary with observed fitted medians, not a falsely optimistic score.
tr0,va0=folds[0];fold_median=float(np.nanmedian(X[dev[tr0],1]));dev_median=float(np.nanmedian(X[dev,1]));global_median=float(np.nanmedian(X[:,1]))
# Subgroup threshold fixed using development outcome distribution, then audited on test.
threshold=float(np.quantile(y[dev],.9));tail=y[test]>=threshold;subgroups=[]
for label,mask in [('Below development p90',~tail),('At/above development p90',tail)]:
    rr=res[mask];subgroups.append([label,int(mask.sum()),float(np.sqrt(np.mean(rr**2))),float(np.mean(rr))])
# A new fictional future population changes support AND conditional mean, on purpose.
futureX,futurey=generate(200,shift=True);futurepred=smear*np.exp(final.predict(futureX));future_err=futurey-futurepred
future=dict(n=len(futurey),rmse=float(np.sqrt(np.mean(future_err**2))),bias=float(future_err.mean()),outside=float(np.mean(futureX[:,0]>np.max(X[dev,0]))),distance_min=float(futureX[:,0].min()),distance_max=float(futureX[:,0].max()))
fr=fold_results[best];pooled=float(np.sqrt(sum(row[1] for row in fr)/sum(row[0] for row in fr)));meanroot=float(np.mean([row[2] for row in fr]));assert np.isclose(pooled,min(row[1] for row in search));assert len(set(dev)&set(test))==0
print(json.dumps(dict(seed=660913,n=len(y),development_n=len(dev),test_n=len(test),loss=loss,bias_variance=sim,criteria=criteria,example_interval=example_interval,search=search,selected_alpha=best,folds=fr,pooled_rmse=pooled,mean_fold_rmse=meanroot,feature_comparisons=feature_comparisons,final_scores=scores,smear=smear,theoretical_smear=float(np.exp(.28**2/2)),median_rmse=median_rmse,log_rmse=log_rmse,training_rmse=float(np.sqrt(np.mean((y[dev]-trainpred)**2))),coefficients=coef,nonzeros=len(coef),path=path,dual_gap=float(est.dual_gap_),iterations=int(est.n_iter_),fold_size_median=fold_median,dev_size_median=dev_median,all_size_median=global_median,tail_threshold=threshold,subgroups=subgroups,future=future,scaling_example=scaling_example,scatter=np.column_stack([y[test],testpred]).tolist(),tail_rows=[[int(test[i]),float(y[test][i]),float(testpred[i]),float(res[i])] for i in np.argsort(y[test])[-5:][::-1]],residual_scatter=np.column_stack([testpred[:40],res[:40]]).tolist(),selected_first=[float(y[test][0]),float(medpred[0]),float(testpred[0])],baseline=base,missing_counts=np.isnan(X[dev]).sum(axis=0).tolist(),train_distance_max=float(np.max(X[dev,0])))))
'''

def build4():
    lesson_number=4
    d=write_lab(4,LAB4,'Original Juniper workshop and three independent sensor-module scale experiments. Seed 440731. Includes custom local-linear LOWESS, OLS geometry, transformations, sensitivity, and development-only model selection.');s=[]
    def add(*a):s.append(section(*a))
    add('juniper-question','Define the regression question',p('Juniper is a fictional workshop that assembles reusable sensor crates. The planning question is how completion time changes with batch size. A descriptive curve summarizes this generated population; a prediction estimates time for a new batch; a causal claim asks what would happen if the same operation were assigned a different batch size. These are distinct targets, even when the fitted equation looks identical.')+p('Our unit is one batch. X is standardized crate units and Y is completion minutes. The dataset has '+str(d['n'])+' independent simulated batches. The observed X range is '+f(d['x_min'])+' to '+f(d['x_max'])+'. A prediction outside that range is an extrapolation, not additional evidence.'),'What must be added before a descriptive slope can justify an operational intervention?','A design and assumptions connecting intervention to outcomes, including treatment definition, confounding, interference and the target population. A good fit alone does not supply them.')
    add('juniper-generator','Know what the simulation assumes',eq('X ∼ Uniform(1,16); Z ∼ N(0,1), independent.<br>Y = 20 + 5X + 0.18X² + 5 sin(X/3) + (3 + 0.35X)Z.')+p('The original generator uses seed 440731. The conditional mean is the deterministic part and the conditional standard deviation grows with X. This lets us distinguish a fitted approximation from a known teaching truth. None of the observations describe a real workshop. The downloadable script generates every row locally before fitting anything.')+scatter(d['scatter'],'First 36 generated batches, in generation order','Batch size','Completion minutes'),'Does larger conditional variance change E[Y|X]?','No. The noise has conditional mean zero. Its changing spread affects uncertainty and prediction risk, while the conditional mean is defined by the deterministic part.')
    add('juniper-bins','Bin means trade detail for stability',p('A bin scatter first partitions X, then computes the mean of X and the mean of Y within each interval. It is not a regression on the original rows. Equal-width bins expose uneven occupancy; quantile bins make counts more uniform but change the meaning of horizontal distances. Never silently treat a mean of bin means as the overall mean when counts differ.')+table(['X lower','X upper (excluded)','Rows','Mean X','Mean minutes'],[[f(a,1),f(b,1),n,f(x),f(y)] for a,b,n,x,y,e in d['bins']],'Six predeclared equal-width bins')+p('These bins all use width 2.5. The boundaries were fixed before examining Y. Rebinning repeatedly until a preferred story appears is a form of specification search.'),'What is lost when we retain only the bin means?','Within-bin dispersion, leverage points and nonlinear structure inside each interval. Counts and the original scatter should accompany the summary.')
    add('juniper-local-smoother','Use LOWESS as a diagnostic',p('Our LOWESS implementation fits a weighted line near each evaluation point. It uses the nearest 35% of observations, tricube weights w = [1 − (distance/bandwidth)³]³ inside the neighborhood, and no robust reweighting pass. The local intercept is the plotted estimate. Larger neighborhoods smooth more but can hide genuine curvature; small ones can follow noise.')+line_chart(d['grid'],{'Generator mean':d['truth'],'OLS':d['ols_curve'],'Local-linear LOWESS':d['lowess']},'Three different descriptions of the mean','Batch size','Minutes')+p('The generator curve is known only because this is a simulation. In practice LOWESS is an exploratory approximation, not an oracle. Estimates at the boundaries rely on one-sided neighborhoods and deserve extra caution.'),'Is every wiggle in the smoother a population feature?','No. Sampling noise, bandwidth and edge behavior can all create or erase apparent shape. Compare defensible settings and assess prediction outside the fitted rows.')
    add('juniper-ols','Specify the best linear approximation',eq('ŷᵢ = b₀ + b₁xᵢ; (b₀,b₁) = argmin Σᵢ(yᵢ − b₀ − b₁xᵢ)².')+p('The fitted line is ŷ = '+f(d['b'][0])+' + '+f(d['b'][1])+'X. Its slope is a constant change in predicted minutes per standardized batch unit. The intercept is the line’s value at zero, which lies outside our sampled support. A model can be linear in its coefficients while including X², log X or a hinge as predictors.')+p('OLS targets squared vertical errors in Y, not geometric distance to the line. In the population, the best linear projection need not equal E[Y|X]. Our curved DGP makes that distinction concrete: the line is a useful simplification only for a stated range and loss.'),'Does a nonzero intercept imply that an empty batch takes that many minutes?','No. The intercept extrapolates to an unsupported value. A substantive zero-batch claim would require an appropriate process model or data there.')
    h=d['hand']
    add('juniper-hand-calculation','Reconstruct a five-row fit',eq('b₁ = Σ(xᵢ−x̄)(yᵢ−ȳ) / Σ(xᵢ−x̄)²; b₀ = ȳ − b₁x̄.')+table(['X','Generated Y','Fitted Y','Residual Y − fitted'],[[f(x,0),f(y,1),f(z),f(e)] for x,y,z,e in zip(h['x'],h['y'],h['fitted'],h['resid'])],'Independent five-row arithmetic example')+p('Here x̄ = '+f(h['xbar'])+', ȳ = '+f(h['ybar'])+', Sxx = '+f(h['sxx'])+' and Sxy = '+f(h['sxy'])+'. Dividing gives b₁ = '+f(h['b'][1])+'; substituting gives b₀ = '+f(h['b'][0])+'. Squaring and adding the five residuals gives SSE = '+f(h['sse'])+'. These rows are newly generated from Y = 7 + 2.5X plus discrete noise, not extracted from the workshop sample.'),'Why must the fitted line pass through (x̄,ȳ)?','The intercept normal equation gives Σeᵢ = 0. Therefore ȳ = b₀ + b₁x̄. This is sample algebra when an intercept is included, not evidence that population errors are mean-zero conditional on X.')
    add('juniper-projection','Separate identities from assumptions',eq('Xᵀe = 0; with an intercept, Σeᵢ = 0.<br>Population exogeneity: E[ε|X] = 0 is a separate assumption.')+p('The numerical residual sum is '+f(d['resid_sum'],10)+' and the X-weighted residual sum is '+f(d['x_resid'],10)+', both zero up to floating-point rounding. OLS makes fitted residuals orthogonal to included regressors even when a relevant variable is omitted. That is why a residual average of zero cannot validate a causal model.')+p('In matrix terms, fitted values project Y onto the column space of the design matrix. Full column rank gives a unique coefficient vector. With exact dependence, fitted values may still be unique while individual coefficients are not.'),'Would adding X² allow residuals to correlate with X² after refitting?','With an intercept and full numerical rank, OLS makes the new residuals orthogonal to X² too. This remains an in-sample identity and does not guarantee out-of-sample adequacy.')
    add('juniper-variation','Keep three denominators visible',eq('TSS = Σ(yᵢ−ȳ)² = ESS + SSE.<br>Training MSE = SSE/n; residual variance estimate = SSE/(n−p); sample variance of Y = TSS/(n−1).')+table(['Quantity','Calculated value','Meaning'],[['TSS',f(d['tss']),'Variation around the sample mean'],['SSE',f(d['sse']),'Squared fitted misses'],['ESS',f(d['ess']),'Fitted variation around the mean'],['RMSE',f(d['rmse']),'Minutes, denominator n'],['Residual SD',f(d['residual_sd']),'Minutes, denominator n − 2'],['Sample variance of Y',f(d['variance']),'Minutes squared, denominator n − 1']],'Distinct variation summaries')+p('The unbiased-error-variance interpretation of SSE/(n−p) needs a correct linear mean model and homoskedastic independent errors. Our first case deliberately violates those conditions. The number is still computable, but its classical interpretation is not automatically warranted.'),'Can sample SD of Y and training RMSE be used interchangeably?','No. One describes variation before conditioning; the other summarizes fitted prediction errors. They answer different questions and use different denominators.')
    add('juniper-rsquared','Interpret R² without promoting it',eq('R² = 1 − SSE/TSS = '+f(d['r2'],4)+'.')+bars(['Explained','Residual'],[d['ess'],d['sse']],'In-sample variation decomposition','Minutes squared')+p('R² is an in-sample proportional reduction in squared deviations relative to the mean-only model. With the same rows, outcome and intercept, adding regressors cannot reduce ordinary R². That makes it a fit summary rather than a complexity-adjusted model-choice rule. Out-of-sample R² may be negative when predictions lose to the declared reference.')+p('R² is not the fraction of outcomes caused by batch size. It is also not directly comparable across different outcome transformations, samples or weights.'),'If R² rises when X³ is added, has the model earned deployment?','No. Evaluate the extra flexibility using held-out predictions, a decision-relevant loss and the intended deployment population.')
    add('juniper-residual-pattern','Read residuals against predictors',p('A residual is observed minus fitted. Positive means the line underpredicts; negative means it overpredicts. A curved pattern in residuals against X indicates missed mean structure. A fan shape indicates changing spread, although a misspecified mean can also distort apparent variance. A histogram alone collapses away these relationships.')+scatter(d['residual_scatter'],'Residuals for the first 36 generated batches','Batch size','Observed − fitted minutes')+table(['Bin midpoint summary: mean X','Mean residual'],[[f(a[3]),f(a[5])] for a in d['bins']],'Bin residual averages, using every row')+p('Use the full lab to inspect every observation. The plotted subset is fixed as the first 36 rows in generation order, not selected for an attractive pattern.'),'Could a symmetric residual histogram coexist with a badly wrong mean?','Yes. Positive misses at the ends and negative misses in the middle can yield a symmetric overall distribution while revealing a systematic curve against X.')
    t=d['trans']
    add('sensor-scale-contract','Choose the outcome scale deliberately',p('We now switch to three independent fictional sensor-module experiments so that each functional form has a clear population meaning. They share X ∼ Uniform(1,12), but their outcomes are separately generated. The log-level case uses log Y = 2.8 + 0.11X + Normal(0,0.2²). The level-log case uses Y = 40 + 15 log X + Normal(0,4²). The log-log case uses log Y = 2 + 0.7 log X + Normal(0,0.18²).')+p('A log is appropriate only for strictly positive values with a meaningful ratio interpretation. Adding an arbitrary constant to accommodate zeros changes the estimand and can change conclusions. Explain whether a zero represents absence, censoring, a structural category or a measurement problem before deciding on a model.'),'Why not compare all three models using R²?','They describe different generated outcomes and, for two cases, a different scale. Even on one dataset, a log-scale fit statistic does not by itself rank original-scale prediction quality.')
    add('sensor-log-level','Translate a log-level coefficient',eq('log ŷ = b₀ + b₁X; exact proportional contrast for ΔX: exp(b₁ΔX) − 1.')+p('The fitted log coefficient is '+f(t['log_level'][1],5)+'. A one-unit X increase corresponds to '+f(t['pct_one'],2)+'% in the exponentiated fitted log. The approximation 100b₁% is useful only for small changes. The relationship is multiplicative on the outcome scale even though the predictor is not logged.')+line_chart(t['grid'],{'Exponentiated fitted log':t['log_level_median'],'Smearing-adjusted mean':t['log_level_mean']},'A straight log relationship becomes a curve','Module input units','Output units'),'Does this coefficient necessarily describe a proportional change in the arithmetic conditional mean?','Only with an appropriate retransformation factor whose conditional behavior supports that interpretation. A varying error distribution can make the mean ratio differ from exp(b₁ΔX).')
    add('sensor-retransformation','Distinguish median and arithmetic mean',eq('If log Y = m(X) + ε, E[Y|X] = exp(m(X)) E[exp(ε)|X].')+p('Exponentiating a conditional log mean gives a geometric mean. It is also a conditional median when the log error has median zero. It generally does not give the arithmetic mean. For this independent homoskedastic log-normal experiment, a constant factor is justified by the generator. The empirical smearing factor, the average of exp(fitted log residual), is '+f(t['smear'],5)+'.')+p('A global smearing estimate is not a universal correction. If error spread varies with X, estimate a suitable conditional factor or choose another model. For validation, estimate smearing using training residuals only, never the held-out outcomes.'),'Should every endpoint of a log prediction interval be multiplied by the mean smearing factor?','No. Quantiles transform monotonically by exponentiation. A correction for an arithmetic mean is a different calculation from transforming predictive quantiles.')
    add('sensor-level-log','Read a level-log effect in units',eq('ŷ = b₀ + b₁ log X; change from X to rX: b₁ log r.')+p('Here the fitted slope is '+f(t['level_log'][1])+'. A 10% increase in X gives an exact fitted difference of b₁ log(1.10) = '+f(t['level_ten'])+' output units, regardless of starting X. A one-unit increase in X has a different effect depending on the baseline because the local derivative is b₁/X.')+line_chart(t['grid'],{'Level-log fitted outcome':t['level_log_fit']},'Diminishing absolute increments','Module input units','Output units'),'Is a 10% X increase the same as adding 0.10 to log X?','Not exactly. The log increment is log(1.10). Using 0.10 is a small-change approximation, not the exact transformation.')
    add('sensor-log-log','Interpret elasticity and finite changes',eq('log ŷ = b₀ + b₁ log X; elasticity = b₁.<br>Exact fitted percentage difference for multiplier r: 100(rᵇ¹ − 1).')+p('The estimated elasticity is '+f(t['log_log'][1],5)+'. A 10% larger input corresponds to '+f(t['pct_ten'],2)+'% in the exponentiated fitted outcome. The coefficient is a local percentage response, not a percentage-point change in an outcome rate. For finite changes use the power expression, and state whether you are discussing a median, geometric mean or arithmetic mean.')+line_chart(t['grid'],{'Log-log exponentiated fit':t['log_log_fit']},'An elasticity implies a power curve','Module input units','Output units'),'If X doubles, should the fitted percent change be reported as 100b₁%?','No. Use 100(2ᵇ¹ − 1). The local derivative interpretation does not turn a large discrete change into a linear percentage shortcut.')
    i=d['influence']
    add('juniper-leverage','Separate leverage, outliers and influence',p('Return to Juniper. We append one deliberately constructed stress-test row, X = 35 and Y = 280, far beyond the generated support. Leverage measures how unusual its predictor position is; a residual measures vertical surprise conditional on the fit; influence measures how much an estimate changes when that row is perturbed or removed. They are related but not synonymous.')+eq('hᵢ = xᵢᵀ(XᵀX)⁻¹xᵢ; Dᵢ = [eᵢ²/(p s²)] × hᵢ/(1−hᵢ)².')+p('The largest Cook’s distance belongs to row '+str(i['index'])+' (zero-based): h = '+f(i['h'])+', residual = '+f(i['resid'])+' and Cook’s D = '+f(i['cook'])+'. The original slope is '+f(i['slope_original'])+'; with the stress row it is '+f(i['slope_augmented'])+'. These are sensitivity calculations, not a recommended deletion rule.'),'Should an influential row automatically be removed?','No. First verify measurement and scope. A valid unusual case may be exactly the case the decision must accommodate. Report sensitivity and justify any sample restriction independently of the preferred result.')
    se=d['sensitivity']
    add('juniper-selection','Expose measurement and selection choices',p('Two new sensitivity calculations use the same workshop outcomes. First, we replace X with X plus independent Normal(0,3²) measurement noise. Second, we retain only rows whose outcome exceeds the sample median. The clean slope is '+f(se['clean'])+', the noisy-predictor slope is '+f(se['noisy'])+', and the selected-sample slope is '+f(se['selected'])+' using '+str(se['selected_n'])+' rows.')+p('Classical attenuation is a population result for a correctly specified linear model with additive independent predictor error; our nonlinear example is only an illustration, not a proof of that formula. Selection on the outcome changes the conditional distribution being studied. A valid numerical domain and absence of missing cells do not establish representative measurement or sampling.'),'Does conditioning on high outcomes merely remove “bad data”?','No. It creates a different target population and can alter the relationship between X and errors. State the selection mechanism before interpreting the fitted slope.')
    add('juniper-validation-contract','Separate fitting, selection and evaluation',p('Before the predictive comparison, the lab uses a fixed random split: '+str(d['development_n'])+' development rows and '+str(d['test_n'])+' final evaluation rows. Candidate specifications are line, quadratic, cubic and a continuous hinge with a predeclared knot at X = 8. Five development folds choose the model by pooled squared prediction error. Only the selected specification receives a final test score.')+ul('Training rows estimate coefficients.','Development validation compares candidates.','The held-out final sample audits the frozen procedure.')+p('All shapes and the knot were declared before the comparison. The random split imitates a new independent batch from the same generator. It does not imitate a new factory, a future process change or an extreme-size batch.'),'If the final score disappoints, can you select the second-best candidate on that same final sample?','You can diagnose the failure, but selecting again turns that sample into development data. A revised procedure needs a genuinely new final evaluation or another defensible validation design.')
    q=d['quadratic']
    add('juniper-polynomial','Interpret polynomial terms together',eq('ŷ = b₀ + b₁X + b₂X²; local slope = b₁ + 2b₂X.')+p('The full-sample descriptive quadratic has coefficients '+', '.join(f(v,5) for v in q)+'. At X = 4, 8 and 12, its local slopes are '+', '.join(f(v) for v in d['quadratic_slopes'])+' minutes per unit. The linear coefficient alone is the derivative at X = 0, not the model’s general slope. A cubic adds another changing component.')+line_chart(d['grid'],{k:d['curves'][k] for k in ['line','quadratic','cubic']},'Polynomial shapes on a common outcome scale','Batch size','Minutes')+p('Centering and scaling X can improve conditioning and make coefficient reference points meaningful. With a complete polynomial basis of the same degree, such changes do not alter the fitted curve except for numerical rounding.'),'Does a negative X coefficient imply that increasing X always reduces Y in a quadratic?','No. Evaluate b₁ + 2b₂X over the supported range. Individual polynomial coefficients should not be interpreted as separate additive mechanisms.')
    h=d['hinge']
    add('juniper-hinge','Use a hinge without creating a jump',eq('ŷ = b₀ + b₁X + b₂ max(X−8,0).')+p('The hinge contribution is zero at and below 8, then grows linearly above 8. The fitted descriptive slopes are '+f(d['hinge_slopes'][0])+' below the knot and '+f(d['hinge_slopes'][1])+' above it. The coefficient on the hinge is a change in slope, not the upper-segment slope itself. Continuity is built into the basis, while a jump would require an additional indicator.')+line_chart(d['grid'],{'Continuous hinge':d['curves']['hinge'],'Quadratic':d['curves']['quadratic']},'Two ways to permit a changing slope','Batch size','Minutes')+p('Choosing a knot after scanning all outcomes is model selection. If knot selection is allowed, it belongs inside each development fold, or in a separate training/validation stage. Here the knot is fixed by the teaching design.'),'What happens to the fitted level exactly at X = 8?','Both segment formulas agree because max(X−8,0) equals zero at the knot. Only the slope changes.')
    add('juniper-candidate-scores','Let held-out errors compare complexity',table(['Candidate','Parameters','Training RMSE','Development CV RMSE'],[[r['model'],r['p'],f(r['train_rmse']),f(r['cv_rmse'])] for r in d['validation']],'All scores in completion minutes; same development rows')+p('The declared rule selects '+d['selected']+'. Training error measures fit to rows that estimated the coefficients. Cross-validated error uses a different fit for each held-out fold, so every development row is scored without fitting its own outcome. Model ranking is an estimate with sampling variability, not a timeless ordering of functional forms.')+bars([r['model'] for r in d['validation']],[r['cv_rmse'] for r in d['validation']],'Development comparison only','Cross-validated RMSE'),'Why not average fold RMSEs when fold sizes differ?','Pool squared errors and divide by the total row count, then take one square root. Averaging roots changes the weighting and is not generally the same quantity.')
    add('juniper-final-audit','Audit the frozen prediction procedure',p('After selecting '+d['selected']+' from development cross-validation, the lab refits that specification on all development rows and scores the untouched '+str(d['test_n'])+'-row final sample. Its final RMSE is '+f(d['test_rmse'])+' minutes. No other candidate is selected or retuned using that score.')+p('This is one random holdout, so uncertainty about generalization remains. The score estimates performance for the same synthetic population and squared-error task, not causal effects or arbitrary transport. More repeated development validation can assess selection stability; a larger untouched sample can improve the precision of final performance estimates.'),'May you call this model “validated for all workshops”?','No. The sampling design supports a much narrower statement: estimated prediction performance for new independent batches from this particular generator and supported feature range.')
    add('juniper-decision-loss','Choose a model for the actual decision',p('Under squared loss the optimal population point prediction is E[Y|X]. Under absolute loss it is a conditional median. If late completion is substantially more costly than early completion, an upper conditional quantile may be a better planning target. A model can therefore win one score and be inappropriate for the decision.')+p('A planning recommendation should name the cost of an error, available predictors at the planning moment, supported batch range and fallback for unfamiliar cases. Neither a visually smooth curve nor a high R² establishes these choices. A model that predicts a mean also does not provide a capacity buffer automatically.'),'Would adding a fixed safety margin to every mean prediction solve asymmetric risk?','Not generally. Required buffers can vary with conditional dispersion and the cost ratio. Model and validate the relevant quantile or decision rule directly.')
    add('juniper-handoff','Deliver an auditable regression claim',p('A defensible handoff says: “For independently generated Juniper batches, we compared four predeclared mean-model forms using five-fold development validation. The '+d['selected']+' specification had the smallest development RMSE. Its frozen final-sample RMSE was '+f(d['test_rmse'])+' minutes across '+str(d['test_n'])+' rows. These results concern prediction under squared loss within the simulated process, not intervention effects.”')+ul('Include the unit, outcome, feature availability, generator and seed.','Keep sample exclusions, transformations, smearing and knot choices visible.','Separate descriptive full-sample figures from held-out prediction evidence.','Deliver the executable script, notebook output and calculated results together.')+p('The lab assertions verify the OLS decomposition, normal equations and disjoint final sample. Re-run the notebook from a clean kernel, then change a declared generator assumption and explain which conclusions should survive.'),'What is the most important limitation to carry into the next lesson?','The point estimate alone does not describe sampling uncertainty or an individual future outcome. Lesson 5 adds those distinctions and extends conditional comparisons to several predictors.')
    assert len(s)==24
    (ROOT/'content'/f'lesson{lesson_number}-outline.json').write_text(json.dumps([item['title'] for item in s],indent=2)+'\n')
    render_lesson(4,'Regression as an explicit approximation','Model a fictional workshop, translate nonlinear scales, and test whether a more flexible curve earns its place.',s)

def build5():
    lesson_number=5
    d=write_lab(5,LAB5,'Original Cedar calibration-rig experiment, seed 550829, plus a separate exact-normal interval experiment. Computes conventional and HC3 covariance, finite-sample OVB and FWL identities, interactions, joint tests, and cross-fitted residuals.');s=[]
    def add(*a):s.append(section(*a))
    add('cedar-generalization','Name the uncertainty you are quantifying',p('A coefficient can vary because a new sample would contain different rows. A prediction can miss because a future outcome has fresh noise. A model can fail because the sample or specification does not represent the deployment setting. A confidence interval generally addresses the first source under stated assumptions; it does not absorb the other sources automatically.')+p('We begin with an independent, correctly specified Gaussian experiment to derive classical intervals. We then move to Cedar, a fictional calibration-rig dataset with heteroskedastic errors, categories and interactions. Keeping these cases separate prevents a convenient formula from silently acquiring assumptions that the main example does not satisfy.'),'Does a narrow confidence interval establish transportability to a different process?','No. It may estimate a parameter precisely within the sampled population while saying little about a shifted population, a changed measurement process or an omitted mechanism.')
    add('interval-repeated-samples','An interval is a repeated-sampling procedure',eq('X ∼ Uniform(0,10); Y = 12 + 2X + 4Z; Z ∼ N(0,1).')+p('The independent interval example contains 80 rows. Holding the X design fixed, the lab generates 400 new outcome samples and calculates a two-sided 95% t interval for the slope each time. The fraction covering the known slope 2 is '+f(100*d['coverage'],2)+'%. This finite simulation need not equal 95% exactly. Coverage refers to the long-run behavior of the procedure, not a probability assigned to a fixed frequentist parameter after seeing one interval.')+table(['Repeated sample','Slope estimate','95% lower','95% upper'],[[i+1,f(a),f(b),f(c)] for i,(a,b,c) in enumerate(d['coverage_first'])],'First 16 of 400 independently simulated outcome samples'),'If an observed interval misses 2, was its 95% label necessarily false?','No. A calibrated 95% procedure misses in roughly 5% of repeated samples. Calibration is a property of the procedure under its assumptions, not a guarantee for each realized interval.')
    add('interval-classical-derivation','Derive a slope interval with its assumptions',eq('b = (XᵀX)⁻¹XᵀY; s² = SSE/(n−p).<br>Estimated Var(b) = s²(XᵀX)⁻¹.<br>CIⱼ = bⱼ ± t₁₋α/₂,n₋p × SE(bⱼ).')+p('For the independent Gaussian example, the fitted intercept is '+f(d['interval_b'][0])+', slope '+f(d['interval_b'][1])+', and residual SD '+f(d['interval_s'])+'. There are 78 residual degrees of freedom. Independent normal homoskedastic errors and a correctly specified conditional mean make the t reference exact conditional on the design. Without normality, a large-sample approximation may still be useful, but its justification changes.')+table(['Nominal confidence','Lower slope endpoint','Upper slope endpoint'],[[f(100*a,0)+'%',f(b),f(c)] for a,b,c in d['levels']],'The same coefficient under three confidence levels'),'Why does the interval widen as confidence increases?','The estimate and standard error remain fixed; the critical value grows. More coverage requires a wider acceptance range for repeated-sample variation.')
    add('cedar-robust-covariance','Change uncertainty without changing the fit',eq('HC3 = (XᵀX)⁻¹ [Σ xᵢxᵢᵀ eᵢ²/(1−hᵢ)²] (XᵀX)⁻¹.')+p('HC3 uses each squared residual with a leverage adjustment instead of one common error variance. It leaves the OLS coefficients and fitted values unchanged. It can support asymptotic inference for independent observations under heteroskedasticity and suitable regularity conditions; it does not repair a wrong target, omitted confounding, selection, dependence or a badly chosen mean model.')+p('Cedar’s error SD grows with rig service age. Its main model therefore reports both conventional and HC3 standard errors. The classical covariance is retained as a comparison, not endorsed as calibrated. Clustered or serially dependent observations would need a different covariance design.'),'Does “robust” mean the regression is resistant to all influential observations?','No. HC3 is a heteroskedasticity-consistent covariance estimator with leverage adjustment. It is not robust regression, a cure for contamination or a license to ignore extreme design points.')
    add('interval-difference-test','Test a contrast rather than overlap',eq('Var(bₐ−bᵦ) = Var(bₐ)+Var(bᵦ)−2Cov(bₐ,bᵦ).<br>For cᵀb: SE = √(cᵀ V c).')+p('Two individual confidence intervals cannot generally determine whether their difference is statistically distinguishable from zero. The covariance term matters. Contrasts within one regression share fitted data and often have substantial covariance. Comparing separate group intervals is not a substitute for calculating the group difference directly.')+p('A two-sided test and an interval agree when they use the same estimand, covariance, critical value and significance level: zero is outside the corresponding interval exactly when the test rejects. For nonlinear transformations, transform both endpoints when the transformation is monotone, and report the target scale.'),'Can overlapping 95% intervals accompany a statistically significant difference?','Yes. The standard error of the difference can be sufficiently small, especially with positive covariance. Compute the contrast and its covariance explicitly.')
    add('interval-two-targets','A mean and an individual need different intervals',eq('At predictor vector x₀: ŷ₀ = x₀ᵀb.<br>SE(mean)² = x₀ᵀ V x₀.<br>SE(new outcome)² = x₀ᵀ V x₀ + s² under the classical model.')+p('The mean interval describes uncertainty about the conditional expectation. The prediction interval adds the variation of a new independent outcome around that expectation. Even an enormous training sample cannot eliminate irreducible individual noise. These formulas concern a new row with known predictors, not a new estimate of a noisy or uncertain predictor.')+table(['X','Fitted Y','95% mean interval','95% new-outcome interval'],[[r['x'],f(r['pred']),f(r['mean_lo'])+' to '+f(r['mean_hi']),f(r['pred_lo'])+' to '+f(r['pred_hi'])] for r in d['intervals']],'Classical intervals in the separate Gaussian experiment'),'Why does the prediction interval not shrink to zero as sample size grows?','Parameter uncertainty can shrink, but the future error remains. Conditional outcome variation is not eliminated by knowing the population mean exactly.')
    ir=d['intervals']
    add('interval-design-center','Locate where the design is informative',eq('Simple regression: Var(ŷ₀ | X) = σ²[1/n + (x₀−x̄)² / Σ(xᵢ−x̄)²].')+p('Mean uncertainty is smallest at the design center and grows away from it. A broad X range improves precision for a slope, while a large sample clustered at nearly one X value may still identify that slope poorly. The lab includes X = 12 to illustrate extrapolation beyond the generating interval. Its formula can be evaluated there, but the functional-form assumption does much more of the work.')+line_chart([r['x'] for r in ir],{'Mean lower':[r['mean_lo'] for r in ir],'Mean upper':[r['mean_hi'] for r in ir],'Prediction lower':[r['pred_lo'] for r in ir],'Prediction upper':[r['pred_hi'] for r in ir]},'Two uncertainty budgets over the predictor range','X in the Gaussian experiment','Outcome units'),'Does a software interval at an unsupported X validate extrapolation?','No. It quantifies uncertainty under the assumed model. Model misspecification outside observed support is not automatically reflected in the formula.')
    r=d['intervals'][1]
    add('interval-worked-budget','Work one prediction from the covariance',p('At X = '+str(r['x'])+', the separate Gaussian fit predicts '+f(r['pred'])+'. The estimated mean standard error is '+f(r['se_mean'])+'; adding the residual variance produces a new-outcome standard error of '+f(r['se_pred'])+'. The resulting 95% mean interval is '+f(r['mean_lo'])+' to '+f(r['mean_hi'])+', compared with '+f(r['pred_lo'])+' to '+f(r['pred_hi'])+' for a future outcome.')+p('For a heteroskedastic model, adding one global s² to an HC3 mean variance does not create a justified individual prediction interval. You need a model or method for conditional outcome variation, such as a correctly specified distributional model, calibrated quantile method or an appropriately designed predictive calibration procedure.')+p('If a model is fitted to log outcomes, a log-scale mean interval is not automatically an arithmetic-mean interval after exponentiation. That target requires retransformation and potentially uncertainty in the correction factor.'),'What extra quantity separates the two classical intervals?','The conditional variance of a new error. Parameter uncertainty appears in both; fresh outcome noise appears only in the prediction interval.')
    add('cedar-data-contract','Introduce Cedar without inheriting the previous model',p('Cedar contains '+str(d['n'])+' simulated calibration rigs. Y is throughput in units/hour; E is service age in years; D marks a powered fixture; A is a tool setting between zero and one; bench category is amber, blue or copper. The generator uses seed 550829 and all features are available before calibration.')+eq('E ∼ Uniform(0,12); P(D=1|E) = logistic(−1+0.2E); E<sub>c</sub> = E−6.<br>Y = 70 + 2E<sub>c</sub> − 0.08E<sub>c</sub>² + 5D + 1.1D E<sub>c</sub> + 4A + 0.7E<sub>c</sub>A + bench offset + (3+0.4E)Z.')+p('A is independent Uniform(0,1), Z is independent standard normal, and bench probabilities are 0.40, 0.35 and 0.25 with offsets 0, 4 and −3. Older rigs are more likely to have powered fixtures. This association makes the unconditional fixture contrast different from a comparison at a common service age.'),'Why explicitly change the data passport between examples?','Units, sampling, error structure and estimands changed. Carrying a previous case’s assumptions forward without restating them would make the inference misleading.')
    add('cedar-conditional-comparison','Read an adjusted coefficient as a conditional comparison',eq('Additive approximation: Ŷ = b₀ + bD D + bE(E−6).')+p('In the same-row additive model, the fixture coefficient is '+f(d['add'][1])+' units/hour. It compares the two fitted fixture groups at a common service age while imposing parallel service-age slopes. The unadjusted difference is '+f(d['short'][1])+'. Adding a variable changes the comparison being made; it does not automatically reveal a “true effect.”')+bars(['No fixture','Powered fixture'],d['group_means'],'Unadjusted group means','Throughput units/hour')+p('The known generator has fixture-by-age interaction and curvature, so this additive fit is deliberately incomplete. Its coefficient is a linear projection coefficient, not the constant conditional fixture contrast of the full generator.'),'What does “holding service age constant” mean algebraically?','Compare two fitted values with the same service-age input and different D. It does not mean the data physically held each rig fixed or randomly assigned its fixture.')
    add('cedar-fixed-rows','Hold the sample fixed when models change',p('Every Cedar coefficient comparison uses the same '+str(d['n'])+' rows. That is crucial: a coefficient can move because controls changed, because rows changed, or both. If a newly added covariate has missing values, first refit the shorter model on the common complete-case sample before attributing the difference to adjustment.')+table(['Fixture group','Mean service years','Mean throughput'],[['No fixture',f(d['experience_means'][0]),f(d['group_means'][0])],['Powered fixture',f(d['experience_means'][1]),f(d['group_means'][1])]],'Composition differs across fixture groups')+p('A complete-case sample can itself be selected. A defensible workflow records eligibility, missingness, measurement units and duplicate handling before interpreting adjusted coefficients. Here no outcome-based filtering or missing-data deletion occurs.'),'Can the exact omitted-variable identity survive using different rows in the short and long models?','Not in its usual same-sample form. Its algebra assumes identical outcomes, rows and weights, plus the stated nested regressors.')
    add('cedar-partial-variation','Precision depends on what controls leave',eq('Residualize D on controls Z: rD = D − Z(ZᵀZ)⁻¹ZᵀD.<br>Homoskedastic Var(bD | X) = σ² / (rDᵀrD).')+p('Before controlling for age, the centered fixture sum of squares is '+f(d['D2'])+'. After removing its linear association with centered age, the residual sum of squares is '+f(d['rD2'])+'. The second quantity supplies the independent design variation that identifies the additive fixture coefficient. More controls can lower unexplained outcome noise while also consuming the variation used to estimate a particular coefficient.')+p('Exact dependence prevents separate identification. Near dependence inflates uncertainty and can make coefficient values unstable even when combined predictions remain reasonably stable. The displayed homoskedastic variance formula is conceptual; Cedar’s reported uncertainty uses HC3 because its error spread changes with E.'),'Does a high overall R² imply every individual coefficient is precise?','No. Predictors may jointly explain Y while being highly correlated with each other. Precision for one coefficient depends on its residual variation after the others are removed.')
    add('cedar-fwl','Reproduce the coefficient by residualizing',eq('Frisch–Waugh–Lovell: bD = (rDᵀrY)/(rDᵀrD),<br>where rY and rD both remove the same control columns, including the intercept.')+p('The lab regresses D on intercept and centered service age, then does the same for Y. Regressing the resulting Y residuals on the D residuals gives '+f(d['fwl'],8)+', exactly the additive fixture coefficient '+f(d['add'][1],8)+' up to rounding. This is a computational identity, not a new identification assumption.')+p('Residualizing only Y, changing rows between the steps or omitting an intercept from just one projection breaks the intended comparison. The two-step coefficient identity does not mean that a naive second-stage standard error automatically has the correct degrees of freedom or covariance treatment.'),'Why residualize the treatment indicator as well as the outcome?','The coefficient must use the part of D not already explained by the controls. Residualizing only Y leaves the denominator’s irrelevant variation in place.')
    add('cedar-omitted-identity','Account for the coefficient movement exactly',eq('Short Y on (1,D): bD<sup>short</sup>.<br>Long Y on (1,D,E<sub>c</sub>): bD<sup>long</sup>, bE<sup>long</sup>.<br>Auxiliary E<sub>c</sub> on (1,D): δD.<br>bD<sup>short</sup> = bD<sup>long</sup> + bE<sup>long</sup> δD.')+p('The long fixture coefficient is '+f(d['add'][1],6)+', the long age coefficient '+f(d['add'][2],6)+', and the auxiliary fixture slope '+f(d['aux'][1],6)+'. Their product is '+f(d['product'],6)+'. Adding it to the long fixture coefficient reconstructs '+f(d['ovb_reconstructed'],6)+', the short coefficient. The observed shift is '+f(d['shift'],6)+'. The script asserts equality numerically.')+p('The sign can be reasoned through before multiplying: fixture status is associated with greater service age, and age has a positive additive partial slope in this sample. Their product raises the unadjusted fixture coefficient.'),'Does this identity require the long regression to be the true population model?','No. It is exact same-sample least-squares algebra. Calling the difference causal omitted-variable bias requires additional assumptions about the population model and the target effect.')
    add('cedar-algebra-versus-bias','Do not rename every difference “bias”',p('The OVB identity explains why coefficients differ between two linear projections. To call the short coefficient biased for a causal effect, specify a structural target and show why the long model identifies it. A control can be a confounder, mediator, collider or proxy; adding it can improve or worsen causal interpretation depending on the data-generating process.')+p('Cedar’s full DGP is disclosed for teaching. In an empirical application it would not be known. A distributional imbalance is a clue to investigate, not proof of a causal pathway. Even in Cedar, the fixture contrast varies with service age, so a single additive fixture coefficient is not the entire response surface.')+ul('Name the estimand before diagnosing bias.','Draw the measurement and assignment story.','Check overlap for the intended contrast.','Distinguish sampling algebra from causal assumptions.'),'If a coefficient barely changes after adding one control, is confounding ruled out?','No. Unobserved confounding can remain, the control may be weakly measured, or offsetting omitted pathways may hide movement.')
    add('cedar-local-slopes','Interpret curvature through a derivative or contrast',eq('Full-model age slope = bE + 2bE² E<sub>c</sub> + bD×E D + bE×A A.')+p('For powered fixtures at tool setting A = 0.5, the fitted local service-age slopes at E = 3, 6 and 9 are '+', '.join(f(v) for v in d['quadratic_slopes'])+' throughput units/hour per service year. Each is a combination of several coefficients. A coefficient labelled “service age” alone refers to the centered reference point and specified interacting predictors.')+p('For a finite change, construct two complete design rows and subtract their fitted values. A derivative is local, while a multi-year contrast follows the whole fitted curve. A quadratic turning point is a property of a fitted equation; it is not a maintenance or retirement recommendation by itself.'),'Can you read the age-squared coefficient as the effect of adding one year?','No. It contributes to the changing slope together with the linear and interaction terms. Use a derivative at stated inputs or an explicit finite contrast.')
    add('cedar-joint-tests','Test several restrictions as one hypothesis',eq('Classical nested F = [(SSE<sub>R</sub> − SSE<sub>U</sub>)/q] / [SSE<sub>U</sub>/(n−p<sub>U</sub>)].<br>Robust Wald W = (Rb)ᵀ[R V<sub>HC3</sub> Rᵀ]⁻¹(Rb), compared asymptotically with χ²<sub>q</sub>.')+p('Here the joint null sets age curvature and fixture-by-age interaction to zero: q = '+str(d['q'])+'. The restricted SSE is '+f(d['restricted_sse'])+' and unrestricted SSE '+f(d['full_sse'])+' with '+str(d['df'])+' residual degrees of freedom. The classical F statistic is '+f(d['F'])+' (p = '+f(d['F_p'],7)+'), but its exact homoskedastic calibration is not valid for this generator. The HC3 Wald statistic is '+f(d['W'])+' (asymptotic p = '+f(d['W_p'],7)+').')+p('Two separate marginal tests do not answer the same joint question. Their covariance matters, and a pair of individually noisy coefficients can be jointly informative. Statistical rejection still does not establish decision importance.'),'Why report the classical F only as a comparison here?','Cedar’s conditional error variance changes with service age. The displayed exact F distribution relies on assumptions that the main DGP intentionally violates.')
    add('cedar-category-coding','Treat category labels as labels',p('Amber, blue and copper are bench types, not equally spaced numbers. With an intercept, use two indicators and an omitted reference category. Including all three indicators creates exact dependence because they sum to the intercept. Changing the reference alters coefficient labels but leaves the fitted comparison surface unchanged.')+table(['Bench','Rows','Unadjusted mean throughput'],[[a,b,f(c)] for a,b,c in d['counts']],'Category sample composition')+p('With amber as reference, the centered full-model intercept is '+f(d['amber_intercept'])+'. With copper as reference it is '+f(d['copper_intercept'])+'. The maximum absolute fitted-value difference after reparameterization is '+f(d['reference_error'],10)+'. This numerical equality is checked in the lab. The raw category means above are not the adjusted indicator coefficients.'),'Why not assign amber = 1, blue = 2 and copper = 3 as one numeric predictor?','That imposes an ordering and equal spacing on the fitted effects. Such a restriction requires substantive justification, not just a convenient code.')
    add('cedar-interacting-fixture','Let the fixture comparison vary with age',eq('Fixture contrast at age E = bD + bD×E(E−6).')+p('Centering age at six makes the main fixture coefficient answer a meaningful reference-point question. The interaction coefficient says how the fixture contrast changes per additional service year. Neither coefficient alone describes the contrast at every age. HC3 uncertainty for each contrast uses the full covariance, including the covariance between main and interaction terms.')+table(['Service age','Adjusted fixture contrast','HC3 95% lower','HC3 95% upper'],[[f(a,0),f(b),f(c),f(e)] for a,b,c,e in d['contrasts']],'Normal-reference robust intervals for the fixture contrast')+line_chart([r[0] for r in d['contrasts']],{'Fitted contrast':[r[1] for r in d['contrasts']],'Lower':[r[2] for r in d['contrasts']],'Upper':[r[3] for r in d['contrasts']]},'The conditional fixture difference is not constant','Service years','Throughput difference'),'What happens to fitted values if age is centered somewhere else?','They remain the same when all lower-order and interaction terms are transformed consistently. Main-effect coefficients change their reference point, not the underlying fitted surface.')
    add('cedar-continuous-interaction','Read a continuous interaction as a surface',eq('Tool-setting slope at service age E = bA + bE×A(E−6).')+p('At E = 3, 6 and 9, the fitted tool-setting slopes are '+', '.join(f(v) for v in d['continuous_slopes'])+' throughput units/hour per full unit of A. For a smaller setting change multiply by that change while holding age fixed. A full-unit difference spans the entire generated tool-setting range, so it should not be treated as a typical local adjustment.')+p('An interaction describes dependence of one fitted slope on another predictor. Preserve the associated lower-order terms unless a well-justified restriction says otherwise. Explain the surface with a small number of supported contrasts, rather than listing coefficients without their reference points.'),'Does a positive interaction guarantee that increasing either predictor always increases the outcome?','No. Each local slope combines its main effect and the interaction evaluated at the other predictor. The sign can vary across the supported range.')
    add('cedar-coefficient-audit','Keep the whole parameterization inspectable',table(['Term','Estimate','Conventional SE','HC3 SE'],[[name,f(b),f(se),f(hc)] for name,b,se,hc in d['fullcoef']],'Full Cedar model, same 260 rows')+p('The intercept refers to service age six, no fixture, tool setting zero and an amber bench. The printed coefficient count is meaningful only if the design is full rank; the script uses an identifiable basis. Conventional and HC3 standard errors can differ in either direction. “Robust” does not mean “always larger.”')+p('The full model contains known mean terms from the teaching DGP. That makes it useful for demonstrating covariance calculations, but real modeling rarely enjoys this certainty. Interpretation still depends on measurement, common support, target population and the purpose of adjustment.'),'Should you select the covariance estimator that makes the preferred coefficient significant?','No. Choose the uncertainty method to match sampling and dependence assumptions, not the desired p-value.')
    add('cedar-residual-sign','Read observed-versus-predicted axes carefully',p('The horizontal axis below is observed throughput and the vertical axis is cross-fitted predicted throughput. A point above the diagonal has predicted greater than observed, so its residual Y − Ŷ is negative. A point below the diagonal is underpredicted and has a positive residual. Reversing the axes reverses the visual rule but not the residual definition.')+scatter(d['scatter'],'First 36 cross-fitted Cedar predictions','Observed throughput','Predicted throughput',True)+p('Every displayed prediction comes from a model fitted without that row. Cross-fitted RMSE is '+f(d['oof_rmse'])+' units/hour, compared with in-sample RMSE '+f(d['training_rmse'])+'. Neither number is a causal diagnosis of an individual rig.'),'A point lies well above the diagonal. Is observed throughput unusually high relative to the prediction?','No. The model predicts more than was observed. Its residual is negative; the system may be overpredicting that row or may have missed relevant context.')
    add('cedar-residual-inquiry','Use large residuals as questions, not verdicts',table(['Row ID (zero-based)','Observed','Cross-fitted prediction','Residual','Service years'],[[i,f(y),f(yh),f(e),f(age)] for i,y,yh,e,age in d['residual_rows']],'Five largest absolute cross-fitted residuals')+p('A residual shortlist is an investigation queue: verify units, measurement timing, inputs available at prediction, omitted operating conditions and model scope. Rows do not deserve a judgment merely because they disagree with a fitted average. The residuals selected here are the largest absolute values, so their apparent extremity is expected after selection.')+scatter(d['resid_plot'],'Residuals versus cross-fitted predictions, first 36 rows','Cross-fitted throughput','Observed − predicted')+p('For repeated measurements from one rig or one facility, split by that grouping if the intended task is a new rig or facility. Random row folds can otherwise leak stable identity or environment information.'),'Why use cross-fitted rather than training residuals for a performance shortlist?','Training predictions have already adapted to each row’s outcome. Cross-fitting reduces that self-fit advantage, although it does not eliminate selection effects or guarantee a fair interpretation.')
    add('cedar-inference-handoff','Deliver a conditional, testable claim',p('A careful Cedar handoff separates four statements: the unadjusted fixture difference is '+f(d['short'][1])+' units/hour; the additive age-adjusted coefficient is '+f(d['add'][1])+'; the full model permits age-varying contrasts; and robust uncertainty addresses heteroskedasticity under independent sampling. The exact additive coefficient change is verified by the auxiliary regression, not explained causally by algebra alone.')+ul('For a coefficient: name the contrast, reference point and covariance method.','For an average: use uncertainty in the conditional mean.','For a new outcome: add the appropriate conditional outcome variation.','For action: investigate design, measurement and consequences beyond the fitted residual.')+p('The notebook reproduces all estimates, interval endpoints, covariance calculations, tests and residual rankings. Its assertions verify FWL, the omitted-variable identity and reference-category invariance. Next, Lesson 6 turns the emphasis from explaining a fitted sample to forecasting genuinely new cases.'),'What is the strongest unsupported leap to avoid?','Do not turn an adjusted association or a residual into a causal conclusion or an individual operational judgment without the additional evidence that decision requires.')
    assert len(s)==24
    (ROOT/'content'/f'lesson{lesson_number}-outline.json').write_text(json.dumps([item['title'] for item in s],indent=2)+'\n')
    render_lesson(5,'Uncertainty and conditional comparisons','Build intervals for the right target, reconstruct coefficient changes, and interpret interactions without losing the comparison.',s)

def build6():
    lesson_number=6
    d=write_lab(6,LAB6,'Original Mica dispatch-cost dataset, seed 660913. A completely fold-safe log-target LASSO pipeline, within-fold smearing, development-only tuning, frozen final evaluation, and a separately generated transport stress test. Includes independent simulations for loss, bias/variance and information criteria.');s=[]
    def add(*a):s.append(section(*a))
    add('mica-prediction-contract','Write the prediction contract first',p('Mica is a fictional dispatch network. At request intake, it must forecast the final job cost in credits using only information already known: requested distance, package size, priority, a weather index and origin hub. A forecast made after the job is complete would be a different task even if the outcome column were unchanged.')+ul('Unit: one independent dispatch request.','Scoring moment: intake, before service and billing.','Primary target: expected cost for an eligible new request.','Primary loss: squared error on the original credit scale.','Scope: the generated operating environment and supported input range.')+p('A prediction contract should also state latency, missing-feature handling and a fallback when required inputs are unavailable. We use synthetic costs rather than empirical prices so every assumption and every generated row can be disclosed and reproduced.'),'Would a feature recorded only after delivery be eligible because it predicts cost well?','No. It violates the scoring-time information boundary. High predictive association cannot make unavailable future information deployable.')
    add('mica-loss-target','Let the cost of an error define the target',eq('Squared loss → conditional mean.<br>Absolute loss → conditional median.<br>Asymmetric absolute loss cᵤ(Y−a)₊ + cₒ(a−Y)₊ → quantile τ = cᵤ/(cᵤ+cₒ).')+p('An independent log-normal simulation makes the distinction concrete. With underprediction costing four times overprediction, the target is the 80th percentile rather than the mean or median. The table evaluates all three choices on the same 3,000 generated outcomes. Its squared-loss units are credits squared; the other losses are in credits, with cost weights for the asymmetric column.')+table(['Point rule','Prediction','Mean squared loss','Mean absolute loss','Weighted absolute loss'],[[a]+[f(v) for v in row] for a,*row in d['loss']],'One distribution, three loss functions')+p('For classification, a calibrated probability is not yet an action. A binary decision threshold also depends on false-positive and false-negative costs, and often operational capacity.'),'Why can two well-calibrated models disagree about the best point forecast?','They may target different functionals. The mean, median and a cost-weighted quantile need not coincide in a skewed distribution.')
    add('mica-score-denominator','Keep prediction, residual and score distinct',eq('eᵢ = yᵢ−ŷᵢ; MSE = Σeᵢ²/n; RMSE = √MSE; MAE = Σ|eᵢ|/n.')+p('A prediction is one estimated outcome. A residual is one signed miss. A score aggregates misses over a specified sample. RMSE and MAE are in credits; MSE is in credits squared. Mean signed residual reports direction of average error but can be near zero when large positive and negative errors cancel.')+p('Compare models on the same rows, target scale and information set. A baseline fitted on development data establishes whether complexity adds practical value. Our final baseline predicts the development-sample arithmetic mean for every final row. It cannot peek at the final-sample mean.')+p('Large misses receive disproportionate influence under squared loss. Removing or capping high-cost cases changes the scoring population and must be declared before the final audit.'),'Can a model with smaller RMSE have larger MAE?','Yes. One may reduce rare large misses while making many ordinary misses slightly worse. The decision’s loss should determine which trade-off matters.')
    add('mica-bias-variance','Explain optimism with repeated training samples',eq('At x: E[(Ynew−f̂(x))²] = σ² + Bias[f̂(x)]² + Var[f̂(x)].')+p('The identity averages over new training samples and independent future noise under a fixed DGP. It is not a decomposition obtained by labelling one fitted residual as “bias” or “variance.” Our separate simulation generates 160 training samples of 45 rows from Y = 8 + 3X + 4X² + Normal(0,2²), X uniform from −1 to 1, then evaluates predictions at a fixed 41-point grid.')+table(['Degree','Mean training MSE','Estimated squared bias','Estimated variance','Noise variance','Estimated new-outcome risk'],[[a]+[f(v) for v in row] for a,*row in d['bias_variance']],'Repeated-sample approximation, equal weight on evaluation grid')+p('The variance term uses the empirical distribution of repeated fitted predictions; the squared-bias term compares their mean with the known curve. The very flexible polynomial can fit training noise and become unstable near the range edges. The risk here is grid-averaged, so do not silently equate it with an integral over another deployment distribution.'),'Why do the cross terms disappear in the population derivation?','Centering the estimator around its expectation and assuming independent mean-zero future error makes the relevant expected products zero. A particular finite sample need not have zero realized cross terms.')
    add('mica-data-generator','Make the new data fully reproducible',eq('log(cost) = 3.2 + 0.035 distance + 0.055 size + 0.12 priority + 0.15 weather<br>+ 0.012 distance×priority + hub offset + 0.08 sin(distance/3) + 0.28Z.')+p('Seed 660913 generates '+str(d['n'])+' requests. Distance is Uniform(1,25), size Uniform(1,12), priority Bernoulli(0.25), weather and Z independent standard normal. Hub probabilities are 0.40, 0.35 and 0.25, with log-cost offsets 0, 0.12 and −0.08. Twenty independent standard-normal distractors create a deliberately richer feature set.')+p('Size and weather are independently missing with probability 0.08, and distractor entries with probability 0.05. Missingness is generated after the outcome, independently of the values; this is a teaching assumption, not a claim that real missingness is harmless. The displayed features contain no post-outcome information. The script generates all observations locally and retains the missingness policy explicitly.'),'Does a synthetic generator guarantee that every fitted candidate is correctly specified?','No. The candidates omit the sine term, impute missing predictors and impose selected bases. Knowing the generator lets us inspect approximation error instead of pretending it is absent.')
    add('mica-feature-hypotheses','Describe candidates as concrete hypotheses',p('The candidate feature groups are cumulative, and each has a clear meaning. Core uses distance, size and priority. Context adds weather and two hub indicators. Expanded adds distance squared, size squared, distance×size and distance×priority, plus twenty noise features. All include an intercept; coefficients are fitted to log cost and predictions are smearing-adjusted to credits.')+table(['Feature set','Design columns including intercept','Training RMSE, credits','Development CV RMSE, credits'],[[a,b,f(c),f(e)] for a,b,c,e in d['feature_comparisons']],'Unpenalized candidate comparison on identical development folds')+p('A printed coefficient count assumes an identifiable design. A numeric category code is not a substitute for indicator columns. Interactions retain lower-order terms. Candidate columns reflect information available at intake, not what becomes known after completion.'),'Why does adding a noise feature sometimes improve a sample score?','Finite samples contain chance correlations. Validation reduces self-fit optimism but itself has sampling noise, especially when many specifications are searched.')
    r=d['example_interval']
    add('mica-interval-recall','A point forecast does not choose an interval target',p('A separate fictional crate-quote experiment uses Y = 45 + 10X + 12X² + Normal(0,5²), with 140 observations and X uniform from −1 to 1. At X = 0.5, a correctly specified quadratic predicts '+f(r[0])+'. Its 95% classical mean interval is '+f(r[1])+' to '+f(r[2])+', whereas the new-outcome interval is '+f(r[3])+' to '+f(r[4])+'. Both are computed from the same fitted coefficients.')+p('The mean interval reflects coefficient uncertainty; the prediction interval adds fresh outcome noise. These are an independent normal-theory demonstration, not valid uncertainty bands silently attached to Mica’s tuned LASSO. Penalization, selection, missingness and a transformed outcome require a prediction-uncertainty method designed and calibrated for the actual pipeline.')+eq('SE(mean)² = x₀ᵀ V x₀; SE(new outcome)² = x₀ᵀ V x₀ + s² under the stated Gaussian model.'),'Can the ordinary OLS standard-error formula be applied unchanged to selected LASSO coefficients?','No. Penalization and data-dependent selection change the estimator’s distribution. Conventional post-selection coefficient intervals are not justified merely because software prints coefficients.')
    add('mica-log-retransform','Back-transform the correct forecast target',eq('ŷmean(x) = exp(m̂(x)) × ŝ; ŝ = mean of exp(training log residuals).')+p('For the constant-noise log-normal generator, the population factor from the noise alone is exp(0.28²/2) = '+f(d['theoretical_smear'],5)+'. The frozen fitted pipeline’s development-residual smearing factor is '+f(d['smear'],5)+'. It also reflects imperfect fitted structure and imputation, so it need not equal the generator’s factor. A global factor is a modeling choice; conditional residual distributions can differ after missing predictors are imputed.')+p('For the first final row, observed cost is '+f(d['selected_first'][0])+'; exponentiating the fitted log gives '+f(d['selected_first'][1])+'; multiplying by the training smearing factor gives '+f(d['selected_first'][2])+'. Smearing was estimated without any final outcomes. Every CV fold estimates its own factor using that fold’s training residuals.')+p('Exponentiated log quantiles should not automatically receive this mean adjustment. The monotonic transformation of a quantile and correction of an arithmetic mean answer different questions.'),'Why not compute one smearing factor using all rows before cross-validation?','It would learn from held-out outcomes and contaminate validation. The full retransformation procedure belongs inside every training fold.')
    add('mica-likelihood','Connect likelihood to a declared probability model',eq('Independent Gaussian errors: −2 log L = n log(2πσ²) + SSE/σ².<br>At the maximum: σ̂²ML = SSE/n, so −2 log L̂ = n[log(2π)+1+log(SSE/n)].')+p('Holding the observed data fixed, likelihood compares candidate parameter values under a probability model. For independent Gaussian errors with common variance, maximizing likelihood over coefficients is equivalent to minimizing SSE. The likelihood variance estimate divides by n, unlike the unbiased classical error-variance estimator with denominator n−p.')+p('For independent Bernoulli outcomes the log likelihood is Σ[y log p + (1−y)log(1−p)], so the appropriate likelihood changes with the outcome model. Deviance is a comparison to a specified saturated likelihood; it is not always literally identical to negative twice the log likelihood. State the software convention instead of relying on an unlabeled number.'),'Why cannot raw likelihood values from unrelated outcome scales simply be ranked?','They may represent different densities, measures, samples or constants. A transformation requires the appropriate Jacobian to express the likelihood on a common observed-data scale.')
    add('mica-information-criteria','Charge the fit for additional parameters',eq('AIC = −2 log L̂ + 2k.<br>BIC = −2 log L̂ + k log n.')+table(['Polynomial degree','k including error variance','SSE','AIC','BIC'],[[a,b,f(c),f(e),f(g)] for a,b,c,e,g in d['criteria']],'Same 140 crate-quote observations and Gaussian likelihood convention')+p('Here k counts regression coefficients, including the intercept, plus one estimated error variance. Lower values are preferred within this declared comparison. AIC targets expected predictive information loss under its approximation; BIC approximates a model-evidence comparison under different assumptions. Neither is a substitute for checking a realistic prediction task.')+p('Do not compare these original-scale Gaussian values directly with a log-outcome fit’s printed values unless the likelihood is expressed on the same outcome scale. For penalized procedures, the appropriate effective degrees of freedom can differ from the raw number of columns.'),'Can a lower AIC certify transportability to another market or process?','No. It evaluates a relative fit/complexity trade-off under its assumptions and observed data. Distribution shift remains a separate question.')
    add('mica-final-lock','Protect the final sample from selection',p('Before learning any preprocessing parameters, the lab partitions Mica into '+str(d['development_n'])+' development rows and '+str(d['test_n'])+' final evaluation rows using split seed 660914. It fixes five development folds using seed 660915. The declared final procedure is a standardized expanded-design LASSO on log cost, choosing alpha by minimum pooled development RMSE in credits, followed by a development-only refit and smearing correction.')+ul('Development folds compare all predeclared alpha values.','The selected alpha, feature basis, imputation rule, scaling and correction are frozen.','The final sample compares the frozen procedure with its predeclared mean baseline.','Final diagnostics describe limitations; they do not trigger further tuning on that sample.')+p('If the final audit causes revisions, those revisions start a new development cycle. Repeatedly inspecting and optimizing a “test” score makes that dataset validation data regardless of its filename.'),'Is a random split always the appropriate design?','No. Use time, group, location or another structure when it better imitates the intended new case. The random split here matches the independent generator, not every deployment setting.')
    add('mica-fold-pooling','Pool errors before taking a square root',eq('Pooled CV RMSE = √[Σfold SSEfold / Σfold nfold].')+table(['Fold','Rows','Squared-error sum','Fold RMSE'],[[i+1,n,f(ss),f(rm)] for i,(n,ss,rm) in enumerate(d['folds'])],'Held-out errors for the selected alpha')+p('The pooled RMSE is '+f(d['pooled_rmse'])+' credits. The unweighted mean of the five fold RMSEs is '+f(d['mean_fold_rmse'])+'. They are not generally identical because the square root is nonlinear, and unequal fold sizes create another weighting difference. Keep every held-out prediction attached to its original row so the overall score and subgroup diagnostics can be reconstructed.')+p('Choosing alpha from these same scores creates selection optimism. The CV minimum is development evidence, not the final unbiased performance claim. Nested CV would be appropriate if the objective were to estimate the performance of the entire tuning procedure without a separate final holdout.'),'What exactly is “out of sample” for a CV prediction?','The row’s outcome and learned preprocessing inputs were excluded from that fold’s fitting. It is still part of development and can influence selection through its validation error.')
    add('mica-feature-availability','Treat availability as part of the model',p('A variable can be present in a historical export but absent at the time a forecast would have been made. Outcome leakage includes final billed amount, a settlement flag, post-service status and any proxy determined after the prediction moment. Splitting rows does not cure this kind of temporal availability error.')+p('Mica’s weather index is stipulated to be known at intake; it is not a realized post-delivery weather summary. Missing size and weather are handled by a training-fitted median policy. Deterministic interactions are then defined on the recorded raw inputs, with missingness propagated, and the resulting design columns are separately median-imputed inside the pipeline.')+p('That order is part of the specification. Imputing raw size first and then squaring it is a different pipeline from median-imputing size squared. Neither should be described vaguely as “we filled missing values.”'),'Would an identifier that encodes the final outcome be safe because it is not named “cost”?','No. Audit semantics, lineage and timing, not column names. A proxy can leak the target as effectively as a direct outcome field.')
    add('mica-pipeline-boundary','Put every learned step inside each fold',eq('Training fold → median imputer.fit → scaler.fit → LASSO.fit(log Y) → training smearing.<br>Validation fold → imputer.transform → scaler.transform → predict → original-scale score.')+p('The pipeline uses SimpleImputer(strategy="median"), StandardScaler and LASSO. Each candidate alpha gets a freshly fitted pipeline inside each fold. The transform parameters learned from training data are retained for that fold’s validation rows. A final refit learns them once again from the complete development set, and those exact values are used for the final sample.')+p('The lab’s development design has '+str(d['missing_counts'][1])+' missing size entries and '+str(d['missing_counts'][3])+' missing weather entries. StandardScaler uses a population-style within-training standard deviation, with denominator n. Dummy variables are also scaled in this declared workflow, so their penalization depends on prevalence and must be interpreted accordingly.'),'Which steps must be inside the folds if feature selection is added later?','Any selection that learns from the data, whether supervised or unsupervised, belongs inside each training fold. This includes imputation, scaling, transformations with fitted parameters and selected feature lists.')
    add('mica-complexity-score','Ask whether added flexibility earns its place',bars(['Core','Context','Expanded'],[r[3] for r in d['feature_comparisons']],'Unpenalized log-model feature comparison','Development CV RMSE in credits')+p('The context variables contain genuine generator information; the expanded design adds useful shape terms and twenty irrelevant predictors together. The table earlier shows what this particular sample supports. It does not prove that every added feature helps or that all retained coefficients are meaningful. The separate repeated-sample polynomial experiment demonstrates why training fit can keep improving while prediction risk rises sharply.')+p('Compare the entire procedure, not an isolated estimator label. A richer design may need shrinkage, a different missingness policy or more data. The result is conditional on the candidate set, folds, target scale and loss; a low score is not a statement about causal mechanisms.'),'Why should the same folds be reused across candidates?','They make scores paired on the same held-out cases, reducing irrelevant variation in the comparison and making row-level error differences inspectable.')
    add('mica-leakage-check','Identify the leak even when its number is small',p('For the first development fold, the training-only median size is '+f(d['fold_size_median'])+'. The median using all development rows is '+f(d['dev_size_median'])+', and using development plus final rows it is '+f(d['all_size_median'])+'. Only the first is appropriate for fitting that fold’s imputer. The complete-development median is appropriate for the final refit, but never for the earlier fold training.')+p('A small difference in these particular medians does not make the leaked procedure correct. Validation is a simulation of future use, when unseen inputs and outcomes cannot help fit preprocessing. The direction and magnitude of leakage bias vary; leakage does not guarantee a more flattering score in every realized sample.')+ul('Do not compute global medians before splitting.','Do not choose categories, knots or selected features from the final sample.','Do not use held-out outcomes to estimate a smearing factor.','Do not inspect test residuals and then quietly retune alpha.'),'Does “unsupervised” preprocessing automatically make global fitting harmless?','No. Learning its parameters from evaluation rows uses information unavailable when fitting for a new case. Keep the training/evaluation boundary intact unless a different transductive task is explicitly intended.')
    a=d['scaling_example']
    add('mica-lasso-objective','Shrink coefficients using a declared objective',eq('Minimize (1/2n)Σ(yᵢ−b₀−xᵢᵀb)² + αΣⱼ|bⱼ|.<br>For one centered predictor with Σxᵢ²/n = 1, z = Σxᵢyᵢ/n:<br>b̂ = sign(z) max(|z|−α,0).')+p('The intercept is not penalized. For a single standardized coordinate, differentiating the quadratic part and applying the absolute-value subgradient produces soft thresholding. With z = '+f(a['soft_z'],2)+' and alpha = '+f(a['alpha'],2)+', the solution is '+f(a['soft_solution'],2)+'. Correlated multivariate predictors require a joint optimization; the one-coordinate expression is an intuition, not a replacement for that fit.')+p('Alpha zero corresponds to unpenalized least squares under this objective, though the script uses LinearRegression rather than asking a LASSO solver to handle zero. Very large alpha can set every slope to zero, leaving an intercept-only log prediction. Objective conventions differ across software, so compare penalties only after checking the scaling.'),'Why can LASSO produce exactly zero coefficients?','The absolute-value penalty has a kink at zero. Its subgradient contains an interval, allowing small data gradients to be balanced without a nonzero coefficient.')
    add('mica-standardized-units','Explain what one scaled coefficient means',table(['Original input','Standardized input'],[[f(x,0),f(z)] for x,z in zip(a['x'],a['z'])],'Independent five-row scaling example')+p('The mean is '+f(a['mean'])+' and StandardScaler-style SD is '+f(a['sd'])+'. A raw slope of '+f(a['raw_slope'],1)+' corresponds to a standardized-coordinate coefficient of '+f(a['scaled_slope'])+' because a one-standard-deviation change is '+f(a['sd'])+' raw units. The predictions match only if the intercept is transformed consistently too.')+eq('zⱼ = (xⱼ−μⱼ)/sⱼ; βraw,ⱼ = βscaled,ⱼ/sⱼ;<br>b₀,raw = b₀,scaled − Σⱼ βscaled,ⱼ μⱼ/sⱼ.')+p('Without scaling, a penalty can favor one variable merely because its units make its coefficient numerically small. With polynomial and interaction columns, a coefficient describes a change in one design column, not necessarily a feasible isolated change in one raw feature. Use complete design-row contrasts for those inputs.'),'Can deployment recompute the mean and SD separately for each new batch of requests?','Not for this frozen pipeline. Use the development-fitted transformation. Re-estimating it changes the meaning of the fitted coefficients and constitutes a changed procedure.')
    add('mica-alpha-search','Tune on the decision scale inside development',table(['Alpha','Pooled development RMSE, credits'],[[f(a,6),f(r)] for a,r in d['search']],'All nine predeclared penalties')+line_chart([r[0] for r in d['search']],{'Development RMSE':[r[1] for r in d['search']]},'The complete penalty search','Alpha, linear scale','RMSE in credits')+p('The selected alpha is '+f(d['selected_alpha'],8)+'. It is the smallest-score candidate under the predeclared rule, not a value discovered from the final sample. Although coefficients minimize a penalized log-scale loss, tuning evaluates smearing-adjusted predictions in original credits. The fitting objective and model-selection loss are therefore explicitly different.')+p('The grid was fixed from 0.001 through 1 on a logarithmic spacing. If a search optimum lies at a boundary, a wider search can be justified during development, but it creates additional selection work. Do not expand a grid in response to final-sample performance.'),'Is the lowest CV number a perfectly measured advantage over its neighbor?','No. It is a noisy selected minimum. Consider stability, practical score differences and a prespecified simplicity rule when appropriate; do not invent a new rule after seeing the final results.')
    keep=d['coefficients']
    add('mica-coefficients-path','A selected coefficient list is not a causal explanation',p('The frozen model retains '+str(d['nonzeros'])+' of 30 penalized design coefficients using a numerical nonzero threshold of 10⁻¹⁰. That is not especially sparse, and several retained columns are known distractors. A zero or nonzero reflects this dataset, scaling, alpha and correlation structure. It is not proof that a feature is scientifically irrelevant or causally active.')+table(['Retained design column','Scaled log coefficient','Training raw-column SD'],[[name,f(b,6),f(sd,4)] for name,b,sd in keep],'All retained coefficients, not a selected favorable subset')+line_chart([r[0] for r in d['path']],{'Distance':[r[1] for r in d['path']],'Priority':[r[3] for r in d['path']],'Weather':[r[4] for r in d['path']]},'Selected coordinate paths, fitted on development only','Alpha, linear scale','Standardized log coefficient')+p('The optimizer used '+str(d['iterations'])+' iterations with dual gap '+f(d['dual_gap'],10)+'. Numerical convergence supports the optimization calculation; it does not validate prediction, causal interpretation or the selected feature set. Path inspection is descriptive here, not a second tuning rule.'),'If two strongly related predictors exchange nonzero status across resamples, must predictions be unstable?','Not necessarily. Similar combinations can yield stable predictions while individual coefficient selection changes. Assess prediction stability and feature-selection stability separately.')
    add('mica-final-evaluation','Open the final sample only after freezing the procedure',table(['Frozen procedure','Final RMSE','Final MAE','Mean signed residual'],[[a,f(b),f(c),f(e)] for a,b,c,e in d['final_scores']],'Untouched '+str(d['test_n'])+'-row final evaluation, all errors in credits')+p('The LASSO procedure’s development training RMSE is '+f(d['training_rmse'])+', whereas its final RMSE is '+f(d['final_scores'][1][1])+'. The final log-scale RMSE is '+f(d['log_rmse'])+' log units, a different metric with a different weighting of misses. The unadjusted exponentiated-log prediction has final RMSE '+f(d['median_rmse'])+' credits; it is shown as a predeclared retransformation diagnostic, not used to change the frozen mean-forecast rule.')+p('This final score is conditional on one split and a finite sample. It estimates performance under the same generator, not a guarantee for tomorrow. If requirements are unmet, report that honestly and return to development without using this sample as a fresh final audit again.'),'Does a final score worse than CV prove there was leakage?','No. Sampling variation and selection optimism can create a gap even in a clean pipeline. Investigate the workflow, but do not infer a specific error from a score difference alone.')
    add('mica-tail-audit','Keep the expensive tail visible',scatter(d['scatter'],'Every final request, with identical observed and predicted scales','Observed cost in credits','Predicted cost in credits',True)+p('All '+str(d['test_n'])+' final rows appear; no expensive case is cropped away. Above the diagonal means overprediction because predicted cost is on the vertical axis. The high-cost threshold is the development outcome 90th percentile, '+f(d['tail_threshold'])+' credits, fixed before inspecting final outcomes. Membership in the outcome-defined tail is a retrospective diagnostic, not an intake-time feature.')+table(['Final subgroup','Rows','RMSE','Mean signed residual'],[[a,b,f(c),f(e)] for a,b,c,e in d['subgroups']],'Tail audit with a development-fixed cutoff')+table(['Row ID','Observed cost','Prediction','Residual'],[[i,f(y),f(yh),f(e)] for i,y,yh,e in d['tail_rows']],'Five highest final observed costs')+p('Conditioning on extreme realized outcomes naturally selects positive noise and can create underprediction even for a calibrated conditional mean. Use this diagnosis to understand risk, not to conclude automatically that adding a tail correction is valid.'),'Can the observed-outcome tail label be used to choose a forecast at intake?','No. The realized outcome is not known then. A prospective routing rule must use available predictors and be validated independently.')
    q=d['future']
    add('mica-transport-stress','A random same-world split is not a future-world test',p('The lab generates a new 200-row fictional future population after freezing the model. Distances now range from 20 to 40 rather than 1 to 25, and the log-cost mean increases by 0.12. Everything else follows the original generator. This is an explicit stress scenario, not a forecast of a real market.')+p('The development maximum distance is '+f(d['train_distance_max'])+'. In the stress population, '+f(100*q['outside'],1)+'% of requests exceed it. Frozen-model RMSE rises to '+f(q['rmse'])+' credits, with mean signed residual '+f(q['bias'])+'. The sign is an observed result of this fitted extrapolation, not something forced by the upward mean shift alone.')+bars(['Same-world final','Shifted scenario'],[d['final_scores'][1][1],q['rmse']],'Different evaluation populations, same frozen model','RMSE in credits')+p('An operational monitoring plan should check feature support, missingness, outcome delay, residual direction and performance by meaningful available subgroups. Define thresholds and responsibility before deployment. A detected shift calls for investigation and a new validation cycle, not automatic reuse of a historical score.'),'Is importance weighting enough to repair any transport failure?','No. Weighting may address certain covariate-distribution changes under overlap and stable conditional relationships. It cannot generally fix absent support or a changed outcome mechanism.')
    add('mica-decision-handoff','Deliver the strongest claim the audit supports',p('A concise Mica decision brief says: “We forecast expected job cost at intake using a fully specified log-target LASSO pipeline. Median imputation, scaling, coefficient fitting and smearing occur inside each development fold. The selected alpha '+f(d['selected_alpha'],8)+' was frozen before final scoring. On '+str(d['test_n'])+' same-generator final requests, RMSE was '+f(d['final_scores'][1][1])+' credits versus '+f(d['final_scores'][0][1])+' for the development-mean baseline. Performance deteriorated materially in the explicitly shifted-distance scenario.”')+ul('Archive the generator, seeds, exact feature order and split assignments.','Keep the complete alpha search, objective convention and optimizer diagnostics.','Retain preprocessing parameters, smearing factor and the frozen final scores.','Document tail limitations, support boundaries and the next evaluation design.')+p('The downloadable script regenerates all data and re-executes every calculation without external files. The notebook includes the fresh execution output. A useful next exercise changes the prediction loss or missingness process before refitting, then explains which parts of the pipeline and evaluation must change.'),'What should happen if the organization changes the task from expected cost to a 90% budget buffer?','Redefine the target and loss, fit an appropriate quantile or predictive distribution procedure, and validate the new decision rule. A mean forecast does not become a calibrated budget buffer by relabelling it.')
    assert len(s)==24
    (ROOT/'content'/f'lesson{lesson_number}-outline.json').write_text(json.dumps([item['title'] for item in s],indent=2)+'\n')
    render_lesson(6,'Prediction that survives new cases','Protect the information boundary, tune a complete pipeline, and audit a frozen model on the scale the decision needs.',s)

if __name__=='__main__':
    build4();build5();build6()
    print('Built synthetic Lessons 4–6: 24 stops each, executed notebooks and result manifests.')
